NAME = 'Wulfila: Bishop Wulfila Gothic Bible'
BOOK = 'Ephesians'

CHAPTERS = {
    1: {
        1: '𐍀𐌰𐍅𐌻𐌿𐍃, 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐍅𐌹𐌻𐌾𐌰𐌽 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌸𐌰𐌹𐌼 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌼 𐌹𐌽 𐌰𐌹𐍆𐌰𐌹𐍃𐍉𐌽 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿. 𐍀𐌰𐍅𐌻𐌿𐍃, 𐌰𐍀𐌰𐌿(𐍃)𐍄𐌰𐌿𐌻𐌿𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐍅𐌹𐌻𐌾𐌰𐌽 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌸𐌰𐌹𐌼 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌼 𐌹𐌽 𐌰𐌹𐍆𐌰𐌹𐍃𐍉𐌽 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿.',
        2: '𐌰𐌽𐍃𐍄𐍃 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌰𐍄𐍄𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿. 𐌰𐌽𐍃𐍄𐍃 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌰𐍄𐍄𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿.',
        3: '𐌸𐌹𐌿𐌸𐌹𐌸𐍃 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌹𐌶𐌴𐌹 𐌲𐌰𐌸𐌹𐌿𐌸𐌹𐌳𐌰 𐌿𐌽𐍃 𐌰𐌽𐌰 𐌰𐌻𐌻𐌰𐌹 𐌸𐌹𐌿𐌸𐌴𐌹𐌽𐌰𐌹 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿. 𐌸𐌹𐌿𐌸𐌹𐌸𐍃 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌹𐌶𐌴𐌹 𐌲𐌰𐌸𐌹𐌿𐌸𐌹𐌳𐌰 𐌿𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌸𐌹𐌿𐌸𐌴𐌹𐌽𐌰𐌹 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿.',
        4: '𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌰 𐌿𐌽𐍃 𐌹𐌽 𐌹𐌼𐌼𐌰 𐍆𐌰𐌿𐍂 𐌲𐌰𐍃𐌰𐍄𐌴𐌹𐌽 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰 𐍅𐌴𐌹𐌷𐌰𐌹 𐌾𐌰𐌷 𐌿𐌽𐍅𐌰𐌼𐌼𐌰𐌹 𐌹𐌽 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐌹𐍃 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹. 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌰 𐌿𐌽𐍃𐌹𐍃 𐌹𐌽 𐌹𐌼𐌼𐌰 𐍆𐌰𐌿𐍂 𐌲𐌰𐍃𐌰𐍄𐌴𐌹𐌽 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰 𐍅𐌴𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌹 𐌾𐌰𐌷 𐌿𐌽𐍅𐌰𐌼𐌼𐌰𐌹 𐌹𐌽 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐌹𐍃 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹.',
        5: '𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐍂𐌰𐌹𐍂𐍉𐌸 𐌿𐌽𐍃 𐌳𐌿 𐍃𐌿𐌽𐌹𐍅𐌴 𐌲𐌰𐌳𐌴𐌳𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿 𐌹𐌽 𐌹𐌽𐌰 𐌱𐌹 𐌻𐌴𐌹𐌺𐌰𐌹𐌽𐌰𐌹 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃, 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐍂𐌰𐌹𐍂𐍉𐌸 𐌿𐌽𐍃 𐌳𐌿 𐍃𐌿𐌽𐌹𐍅𐌴 𐌲𐌰𐌳𐌴𐌳𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌱𐌹 𐌻𐌴𐌹𐌺𐌰𐌹𐌽𐌰𐌹 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃,',
        6: '𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃, 𐌹𐌽 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐌰𐌽𐍃𐍄𐌴𐌹𐌲𐍃 𐍅𐌰𐍃 𐌿𐌽𐍃 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌱𐌹𐌽 𐍃𐌿𐌽𐌰𐌿 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃, 𐌹𐌽 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐌰𐌽𐍃𐍄𐌴𐌹𐌲𐍃 𐍅𐌰𐍃 𐌿𐌽𐍃 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌱𐌹𐌽 𐍃𐌿𐌽𐌰𐌿 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰,',
        7: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐍆𐌰𐌿𐍂𐌱𐌰𐌿𐌷𐍄, 𐍆𐍂𐌰𐌻𐌴𐍄 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌴 𐌸𐌰𐌹𐍂𐌷 𐌱𐌻𐍉𐌸 𐌹𐍃, 𐌱𐌹 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐌹𐍃, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐍆𐌰𐌿𐍂𐌱𐌰𐌿𐌷𐍄, 𐍆(𐍂)𐌰(𐌻𐌴)𐍄 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌴 𐌸𐌰𐌹𐍂𐌷 𐌱𐌻(𐍉𐌸) 𐌹𐍃, 𐌱𐌹 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿(𐌻)𐌸𐌰𐌿𐍃 𐌰(𐌽𐍃)𐍄𐌰𐌹𐍃 𐌹𐍃,',
        8: '𐌸𐍉𐌴𐌹 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌲𐌰𐌽𐍉𐌷𐌹𐌳𐌰 𐌹𐌽 𐌿𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌾𐌰𐌷 𐍆𐍂𐍉𐌳𐌴𐌹𐌽, 𐌸𐍉𐌴𐌹 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌲𐌰𐌽𐍉𐌷𐌹𐌳𐌰 𐌹𐌽 𐌿𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌾𐌰𐌷 𐍆𐍂𐍉𐌳𐌴𐌹𐌽,',
        9: '𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐌿𐌽𐍃𐌹𐍃 𐍂𐌿𐌽𐌰 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃 𐌱𐌹 𐍅𐌹𐌻𐌾𐌹𐌽, 𐍃𐌰𐌴𐌹 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌹𐌼𐌼𐌰 𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐌿𐌽𐍃𐌹𐍃 𐍂𐌿𐌽𐌰 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃 𐌱(𐌹) (𐍅)𐌹𐌻𐌾𐌹𐌽, 𐍃𐌰𐌴𐌹 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌹𐌼𐌼𐌰',
        10: '𐌳𐌿 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌲𐌲𐌾𐌰 𐌿𐍃𐍆𐌿𐌻𐌻𐌴𐌹𐌽𐌰𐌹𐍃 𐌼𐌴𐌻𐌴, 𐌰𐍆𐍄𐍂𐌰 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌸𐍉 𐌰𐌽𐌰 𐌷𐌹𐌼𐌹𐌽𐌰𐌼 𐌾𐌰𐌸~𐌸𐍉 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌹𐌽 𐌹𐌼𐌼𐌰, 𐌳𐌿 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌲𐌲𐌾𐌰 (𐌿)𐍃𐍆𐌿𐌻𐌻𐌴𐌹𐌽𐌰𐌹𐍃 𐌼𐌴𐌻𐌴, 𐌰𐍆𐍄𐍂𐌰 (𐌿𐍃𐍆𐌿)𐌻𐌻𐌾𐌰𐌽 𐌰𐌻𐌻𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌸𐍉 (𐌰𐌽𐌰) 𐌷𐌹𐌼𐌹𐌽𐌰𐌼 𐌾𐌰𐌷 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌹𐌽 𐌹𐌼𐌼𐌰,',
        11: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌻𐌰𐌿𐍄𐍃 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰𐌹 𐍅𐌴𐍃𐌿𐌼, 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐍂𐌴𐌳𐌰𐌽𐌰𐌹 𐌱𐌹 𐍅𐌹𐌻𐌾𐌹𐌽 𐌲𐌿𐌳𐌹𐍃 𐌸𐌹𐍃 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌱𐌹 𐌼𐌿𐌽𐌰 𐍅𐌹𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌻𐌰𐌿𐍄𐍃 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰𐌹 𐍅𐌴𐍃𐌿𐌼, 𐍆𐌰𐌿𐍂(𐌰)𐌲𐌰𐍂𐌴𐌳𐌰𐌽𐌰𐌹 (𐌱)𐌹 𐍅(𐌹)𐌻𐌾𐌹𐌽 𐌲𐌿𐌳𐌹𐍃 𐌸(𐌹𐍃) 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌰𐌻(𐌻)𐌰𐌹𐌼 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌱𐌹 𐌼𐌿𐌽𐌰 (𐍅𐌹)𐌻𐌾𐌹𐌽𐍃 𐍃𐌴𐌹𐌽𐌹𐍃,',
        12: '𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰 𐍅𐌴𐌹𐍃 𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃 𐌸𐌰𐌹 𐍆𐌰𐌿𐍂𐌰𐍅𐌴𐌽𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰 𐍅𐌴𐌹𐍃 𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃 𐌸𐌰𐌹 𐍆𐌰𐌿𐍂(𐌰)𐍅𐌴𐌽𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿,',
        13: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌳 𐍃𐌿𐌽𐌾𐌿𐍃, 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌹 𐌲𐌰𐌽𐌹𐍃𐍄𐌰𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃, 𐌸𐌰𐌼𐌼𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌲𐌰𐍃𐌹𐌲𐌻𐌹𐌳𐌰𐌹 𐍅𐌰𐌿𐍂𐌸𐌿𐌸 𐌰𐌷𐌼𐌹𐌽 𐌲𐌰𐌷𐌰𐌹𐍄𐌹𐍃 𐌸𐌰𐌼𐌼𐌰 𐍅𐌴𐌹𐌷𐌹𐌽, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌳 𐍃𐌿𐌽𐌾𐍉𐍃, 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌹 𐌲𐌰𐌽𐌹𐍃(𐍄)𐌰𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃, 𐌸𐌰𐌼𐌼𐌴𐌹 (𐌲𐌰)𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌽(𐍃) 𐌲𐌰(𐍃𐌹)𐌲𐌻𐌹𐌳𐌰𐌹 (𐍅)𐌰𐌿𐍂𐌸𐌿𐌸 𐌰𐌷𐌼𐌹𐌽 𐌲𐌰(𐌷𐌰)𐌹𐍄𐌹𐍃 𐌸𐌰𐌼𐌼𐌰 𐍅𐌴𐌹𐌷𐌹𐌽,',
        14: '𐌹𐌶𐌴𐌹 𐌹𐍃𐍄 𐍅𐌰𐌳𐌹 𐌰𐍂𐌱𐌾𐌹𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌳𐌿 𐍆𐌰𐌿𐍂𐌱𐌰𐌿𐌷𐍄𐌰𐌹 𐌲𐌰𐍆𐍂𐌴𐌹𐌳𐌴𐌹𐌽𐌰𐌹𐍃, 𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃. 𐌹𐌶𐌴𐌹 𐌹𐍃𐍄 (𐍅𐌰)𐌳𐌹 𐌰𐍂𐌱𐌾𐌹𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌳𐌿 𐍆𐌰𐌿𐍂(𐌱)𐌰𐌿𐌷𐍄𐌰𐌹 (𐌲𐌰)𐍆𐍂𐌴𐌹𐌳𐌴𐌹𐌽𐌰𐌹𐍃, 𐌳𐌿 𐌷𐌰𐌶𐌴𐌹𐌽𐌰𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌹𐍃.',
        15: '𐌳𐌿𐌸𐌸𐌴 𐌾𐌰𐌷 𐌹𐌺, 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌾𐌰𐌷 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌽𐍃 𐌸𐌰𐌽𐍃 𐍅𐌴𐌹𐌷𐌰𐌽𐍃, 𐌳𐌿𐌸𐌸𐌴 𐌾𐌰𐌷 𐌹𐌺, 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽(𐌳𐍃) 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌾𐌰𐌷 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌽𐍃 𐌸(𐌰)𐌽𐍃 𐍅𐌴𐌹𐌷𐌰𐌽𐍃,',
        16: '𐌿𐌽𐍃𐍅𐌴𐌹𐌱𐌰𐌽𐌳𐍃 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌲𐌰𐌼𐌿𐌽𐌳 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐍃 𐌹𐌽 𐌱𐌹𐌳𐍉𐌼 𐌼𐌴𐌹𐌽𐌰𐌹𐌼, 𐌿𐌽𐍃𐍅𐌴𐌹𐌱𐌰𐌽𐌳𐍃 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌲𐌰𐌼𐌿𐌽𐌳 (𐍅𐌰𐌿𐍂𐌺)𐌾𐌰𐌽𐌳𐍃 𐌹𐌽 𐌱𐌹𐌳𐍉𐌼 𐌼𐌴𐌹𐌽𐌰𐌹𐌼,',
        17: '𐌴𐌹 𐌲𐌿𐌸 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌰𐍄𐍄𐌰 𐍅𐌿𐌻𐌸𐌰𐌿𐍃, 𐌲𐌹𐌱𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌷𐌼𐌰𐌽 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐌰𐌽𐌳𐌷𐌿𐌻𐌴𐌹𐌽𐌰𐌹𐍃 𐌹𐌽 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌴𐌹 𐌲𐌿𐌸 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿(𐌽)𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌰𐍄𐍄𐌰 𐍅𐌿𐌻𐌸(𐌰)𐌿𐍃, 𐌲𐌹𐌱𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌷𐌼𐌰𐌽 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐌰𐌽𐌳𐌷𐌿𐌻𐌴𐌹𐌽𐌰𐌹𐍃 𐌹𐌽 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰,',
        18: '𐌹𐌽𐌻𐌹𐌿𐌷𐍄𐌹𐌳𐌰 𐌰𐌿𐌲𐍉𐌽𐌰 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃, 𐌴𐌹 𐍅𐌹𐍄𐌴𐌹𐌸 𐌾𐌿𐍃 𐍈𐌰 𐌹𐍃𐍄 𐍅𐌴𐌽𐍃 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌹𐍃, 𐍈𐌹𐌻𐌴𐌹𐌺𐌿 𐌲𐌰𐌱𐌴𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌰𐍂𐌱𐌾𐌹𐍃 𐌹𐍃 𐌹𐌽 𐍅𐌴𐌹𐌷𐌰𐌹𐌼, 𐌹𐌽𐌻𐌹𐌿𐌷[𐌹]𐍄𐌹𐌳𐌰 𐌰𐌿𐌲𐍉𐌽𐌰 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃, 𐌴𐌹 𐍅𐌹𐍄𐌴𐌹𐌸 𐌾𐌿𐍃 𐍈𐌰 𐌹𐍃𐍄 𐍅𐌴𐌽𐍃 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌹𐍃, 𐍈𐌹𐌻𐌴𐌹𐌺𐌿 𐌲𐌰𐌱𐌴𐌹 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐌰𐍂𐌱𐌾𐌹𐍃 𐌹𐍃 𐌹𐌽 𐍅𐌴𐌹𐌷𐌰𐌹𐌼,',
        19: '𐌾𐌰𐌷 𐍈𐌰 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌿𐍃 𐌼𐌹𐌺𐌹𐌻𐌴𐌹𐌽𐍃 𐌼𐌰𐌷𐍄𐌰𐌹𐍃 𐌹𐍃 𐌹𐌽 𐌿𐌽𐍃 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌼 𐌱𐌹 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌼𐌰𐌷𐍄𐌰𐌹𐍃 𐍃𐍅𐌹𐌽𐌸𐌴𐌹𐌽𐍃 𐌹𐍃, 𐌾𐌰𐌷 𐍈𐌰 𐌿𐍆𐌰𐍂𐌰𐍃𐍃(𐌿)𐍃 𐌼𐌹𐌺𐌹𐌻𐌴𐌹𐌽𐍃 𐌼𐌰𐌷𐍄𐌰𐌹𐍃 𐌹𐍃 𐌹𐌽 𐌿𐌽𐍃 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌼 𐌱𐌹 𐍅𐌰𐌿𐍂(𐍃)𐍄𐍅𐌰 𐌼𐌰𐌷𐍄𐌰𐌹𐍃 𐍃𐍅𐌹𐌽𐌸𐌴𐌹𐌽𐍃 𐌹𐍃,',
        20: '𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌿𐍂𐍂𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐍃 𐌹𐌽𐌰 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰 𐌹𐌽 𐍄𐌰𐌹𐌷𐍃𐍅𐍉𐌽 𐍃𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿, 𐌿𐍂𐍂𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐍃 𐌹𐌽𐌰 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰 𐌹𐌽 𐍄𐌰𐌹𐌷𐍃𐍅𐍉𐌽 𐍃𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼',
        21: '𐌿𐍆𐌰𐍂𐍉 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐍂𐌴𐌹𐌺𐌾𐌴 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌴 𐌾𐌰𐌷 𐌼𐌰𐌷𐍄𐌴 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐌰𐍃𐍃𐌹𐍅𐌴 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐌽𐌰𐌼𐌽𐌴 𐌽𐌰𐌼𐌽𐌹𐌳𐌰𐌹𐌶𐌴 𐌽𐌹 𐌸𐌰𐍄𐌰𐌹𐌽𐌴𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌰𐌹𐍅𐌰, 𐌰𐌺 𐌾𐌰𐌷 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸𐌹𐌽. 𐌿𐍆𐌰𐍂𐍉 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐍂𐌴𐌹𐌺𐌾𐌴 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌴 𐌾𐌰𐌷 𐌼𐌰𐌷𐍄𐌴 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐌰𐍃𐍃𐌹𐍅𐌴 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐌽𐌰𐌼𐌽𐌴 𐌽𐌰𐌼𐌽𐌹𐌳𐌰𐌹𐌶𐌴 𐌽𐌹 𐌸𐌰𐍄𐌰𐌹𐌽𐌴𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌰𐌹𐍅𐌰, 𐌰𐌺 𐌾𐌰𐌷 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸𐌹𐌽.',
        22: '𐌾𐌰𐌷 𐌰𐌻𐌻𐌰 𐌿𐍆𐌷𐌽𐌰𐌹𐍅𐌹𐌳𐌰 𐌿𐍆 𐍆𐍉𐍄𐌿𐌽𐍃 𐌹𐌼𐌼𐌰 𐌾𐌰𐌷 𐌹𐌽𐌰 𐌰𐍄𐌲𐌰𐍆 𐌷𐌰𐌿𐌱𐌹𐌸 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽, 𐌾𐌰𐌷 𐌰𐌻𐌻 𐌿𐍆𐌷𐌽𐌰𐌹𐍅𐌹𐌳𐌰 𐌿𐍆 𐍆𐍉𐍄𐌿𐌽𐍃 𐌹𐌼𐌼𐌰 𐌾𐌰𐌷 𐌹𐌽𐌰 𐌰𐍄𐌲𐌰𐍆 𐌷𐌰𐌿𐌱𐌹𐌸 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽,',
        23: '𐍃𐌴𐌹 𐌹𐍃𐍄 𐌻𐌴𐌹𐌺 𐌹𐍃, 𐍆𐌿𐌻𐌻𐍉 𐌸𐌹𐍃 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽𐌳𐌹𐌽𐍃. 𐍃𐌴𐌹 𐌹𐍃𐍄 𐌻𐌴𐌹𐌺 𐌹𐍃, 𐍆𐌿𐌻𐌻𐍉 𐌸𐌹𐍃 𐌰𐌻𐌻𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽𐌳𐌹𐌽𐍃.',
    },
    2: {
        1: '𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐌼𐌹𐍃𐍃𐌰𐌳𐌴𐌳𐌹𐌼 𐌾𐌰𐌷 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼, 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐌼𐌹𐍃𐍃𐌰𐌳𐌴𐌳𐌹𐌼 𐌾𐌰𐌷 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼,',
        2: '𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐍃𐌹𐌼𐌻𐌴 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌸 𐌱𐌹 𐌸𐌹𐌶𐌰𐌹 𐌰𐌻𐌳𐌰𐌹 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐌱𐌹 𐍂𐌴𐌹𐌺 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌹𐍃 𐌻𐌿𐍆𐍄𐌰𐌿𐍃, 𐌰𐌷𐌼𐌹𐌽𐍃 𐌸𐌹𐍃 𐌽𐌿 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌹𐌽 𐍃𐌿𐌽𐌿𐌼 𐌿𐌽𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐍃𐌹𐌼𐌻𐌴 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌸 𐌱𐌹 𐌸𐌹𐌶𐌰𐌹 𐌰𐌻𐌳𐌰𐌹 𐌸𐌹𐍃 𐌰𐌹𐍅𐌹𐍃, 𐌱𐌹 𐍂𐌴𐌹𐌺 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌹𐍃 𐌻𐌿𐍆𐍄𐌰𐌿𐍃, 𐌰𐌷𐌼𐌹𐌽𐍃 𐌸𐌹𐍃 (𐌽)𐌿 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌹𐌽 𐍃𐌿𐌽𐌿𐌼 𐌿𐌽𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃,',
        3: '𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃𐌼𐌴𐍄𐌿𐌼 𐍃𐌿𐌼𐌰𐌽 𐌹𐌽 𐌻𐌿𐍃𐍄𐌿𐌼 𐌻𐌴𐌹𐌺𐌹𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃, 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌹𐌻𐌾𐌰𐌽𐍃 𐌻𐌴𐌹𐌺𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐌼𐌹𐍄𐍉𐌽𐌴, 𐌾𐌰𐌷 𐍅𐌴𐍃𐌿𐌼 𐍅𐌹𐍃𐍄𐌰𐌹 𐌱𐌰𐍂𐌽𐌰 𐌷𐌰𐍄𐌹𐌶𐌴, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌸𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹. 𐌹𐌽 𐌸𐌰𐌹𐌼𐌴𐌹 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃𐌼𐌴𐍄𐌿𐌼 𐍃𐌿𐌼𐌰𐌽 𐌹𐌽 𐌻𐌿𐍃𐍄𐌿𐌼 𐌻𐌴𐌹𐌺𐌹𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃, 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌹𐌻𐌾𐌰𐌽𐍃 𐌻𐌴𐌹𐌺𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐌼𐌹𐍄𐍉𐌽𐌴, 𐌾𐌰𐌷 𐍅𐌹𐍃𐌿𐌼 𐍅𐌹𐍃𐍄𐌰𐌹 𐌱𐌰𐍂𐌽𐌰 𐌷𐌰𐍄𐌹𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌸𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹.',
        4: '𐌹𐌸 𐌲𐌿𐌸, 𐌲𐌰𐌱𐌹𐌲𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐌹𐌽 𐌰𐍂𐌼𐌰𐌷𐌰𐌹𐍂𐍄𐌴𐌹𐌽, 𐌹𐌽 𐌸𐌹𐌶𐍉𐍃 𐌼𐌰𐌽𐌰𐌲𐍉𐌽𐍃 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐍉𐍃 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌿𐌽𐍃, 𐌹𐌸 𐌲𐌿𐌸, 𐌲𐌰𐌱𐌴𐌹𐌲𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐌹𐌽 𐌰𐍂𐌼𐌰𐌷𐌰𐌹𐍂𐍄𐌴𐌹𐌽, 𐌹𐌽 𐌸𐌹𐌶𐍉𐍃 𐌼𐌰𐌽𐌰𐌲𐍉𐌽𐍃 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐍉𐍃 𐌹𐌽 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌿𐌽𐍃,',
        5: '𐌾𐌰𐌷 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌿𐌽𐍃 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌼𐌹𐌸𐌲𐌰𐌵𐌹𐍅𐌹𐌳𐌰 𐌿𐌽𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 - 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐌽𐌰𐍃𐌹𐌳𐌰𐌹 - 𐌾𐌰𐌷 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌿𐌽𐍃 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼, 𐌼𐌹𐌸𐌲𐌰𐌵𐌹𐍅𐌹𐌳𐌰 𐌿𐌽𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 - 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌹𐌾𐌿𐌼 𐌲𐌰𐌽𐌰𐍃𐌹𐌳𐌰𐌹 -',
        6: '𐌾𐌰𐌷 𐌼𐌹𐌸𐌿𐍂𐍂𐌰𐌹𐍃𐌹𐌳𐌰 𐌾𐌰𐌷 𐌼𐌹𐌸𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿, 𐌾𐌰𐌷 𐌼𐌹𐌸𐌿𐍂𐍂𐌰𐌹𐍃𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌼𐌹𐌸𐌲𐌰(𐍃)𐌰𐍄𐌹𐌳𐌰𐌹 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌹𐌼 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿,',
        7: '𐌴𐌹 𐌰𐍄𐌰𐌿𐌲𐌾𐌰𐌹 𐌹𐌽 𐌰𐌻𐌳[𐌰]𐌹𐌼 𐌸𐌰𐌹𐌼 𐌰𐌽𐌰𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐌴𐌹𐌼 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌿 𐌲𐌰𐌱𐌴𐌹𐌽𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃 𐌹𐌽 𐍃𐌴𐌻𐌴𐌹𐌽 𐌱𐌹 𐌿𐌽𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿. 𐌴𐌹 𐌰𐍄𐌰𐌿𐌲𐌾𐌰𐌹 𐌹𐌽 𐌰𐌻𐌳𐌹𐌼 𐌸𐌰𐌹𐌼 𐌰𐌽𐌰𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐌴𐌹𐌼 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌿 𐌲𐌰𐌱𐌴𐌹𐌽𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃 𐌹𐌽 𐍃𐌴𐌻𐌴𐌹𐌽 𐌱𐌹 𐌿𐌽𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿.',
        8: '𐌿𐌽𐍄𐌴 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌹𐌿𐌸 𐌲𐌰𐌽𐌰𐍃𐌹𐌳𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌽𐌹 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌺 𐌲𐌿𐌳𐌹𐍃 𐌲𐌹𐌱𐌰 𐌹𐍃𐍄; 𐌿𐌽𐍄𐌴 𐌰𐌽𐍃𐍄𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐌽𐌰𐍃𐌹𐌳𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌽𐌹 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌺 𐌲𐌿𐌳𐌹𐍃 𐌲𐌹𐌱𐌰 𐌹𐍃𐍄;',
        9: '𐌽𐌹 𐌿𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼, 𐌴𐌹 𐍈𐌰𐍃 𐌽𐌹 𐍈𐍉𐍀𐌰𐌹, 𐌽𐌹 𐌿𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼, 𐌴𐌹 𐍈𐌰𐍃 𐌽𐌹 𐍈𐍉𐍀𐌰𐌹,',
        10: '𐌰𐌺 𐌹𐍃 𐍃𐌹𐌿𐌼 𐍄𐌰𐌿𐌹, 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌳𐌿 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐌲𐍉𐌳𐌰𐌹𐌼, 𐌸𐍉𐌴𐌹 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌼𐌰𐌽𐍅𐌹𐌳𐌰 𐌲𐌿𐌸, 𐌴𐌹 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌲𐌰𐌲𐌲𐌰𐌹𐌼𐌰. 𐌰𐌺 𐌹𐍃 𐍃𐌹𐌾𐌿𐌼 𐍄𐌰𐌿𐌹, 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌳𐌿 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐌲𐍉𐌳𐌰𐌹𐌼, 𐌸𐍉𐌴𐌹 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌼𐌰𐌽𐍅𐌹𐌳𐌰 𐌲𐌿𐌸, 𐌴𐌹 𐌹𐌽 𐌸𐌰𐌹𐌼 (𐌲𐌰)𐌲𐌲𐌰𐌹𐌼𐌰.',
        11: '𐌳𐌿𐌸𐌸𐌴 𐌲𐌰𐌼𐌿𐌽𐌴𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌾𐌿𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐍃𐌹𐌼𐌻𐌴 𐍅𐌴𐍃𐌿𐌸 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰, 𐌸𐌰𐌹 𐌽𐌰𐌼𐌽𐌹𐌳𐌰𐌽𐍃 𐌿𐌽𐌱𐌹𐌼𐌰𐌹𐍄𐌰𐌽𐌰𐌹 𐍆𐍂𐌰𐌼 𐌸𐌹𐌶𐌰𐌹 𐌽𐌰𐌼𐌽𐌹𐌳𐍉𐌽 𐌱𐌹𐌼𐌰𐌹𐍄 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌷𐌰𐌽𐌳𐌿𐍅𐌰𐌿𐍂𐌷𐍄. 𐌳𐌿𐌸𐌸𐌴 𐌲𐌰𐌼𐌿𐌽𐌴𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌾𐌿𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐍃𐌹𐌼𐌻𐌴 𐍅𐌴𐍃𐌿𐌸 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰, 𐌸𐌰𐌹 𐌽𐌰𐌼𐌽𐌹𐌳𐌰𐌽𐍃 𐌿𐌽𐌱𐌹𐌼𐌰𐌹𐍄𐌰𐌽𐌰𐌹 𐍆𐍂𐌰𐌼 𐌸𐌹𐌶𐌰𐌹 𐌽𐌰𐌼𐌽𐌹𐌳𐍉𐌽 𐌱𐌹𐌼𐌰𐌹𐍄 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰 𐌷𐌰𐌽𐌳𐌿𐍅𐌰𐌿𐍂𐌷𐍄.',
        12: '𐌿𐌽𐍄𐌴 𐍅𐌴𐍃𐌿𐌸 𐌸𐌰𐌽 𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌼𐌴𐌻𐌰 𐌹𐌽𐌿 𐍇𐍂𐌹𐍃𐍄𐌿, 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌹 𐌿𐍃𐌼𐌴𐍄𐌹𐍃 𐌹𐍃𐍂𐌰𐌴𐌻𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍃𐍄𐌴𐌹𐍃 𐌲𐌰𐌷𐌰𐌹𐍄𐌴 𐍄𐍂𐌰𐌿𐍃𐍄𐌴𐌹𐍃, 𐍅𐌴𐌽 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐌲𐌿𐌳𐌰𐌻𐌰𐌿𐍃𐌰𐌹 𐌹𐌽 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹. 𐌿𐌽𐍄𐌴 𐍅𐌴𐍃𐌿𐌸 𐌸𐌰𐌽 𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌼𐌴𐌻𐌰 𐌹𐌽𐌿𐌷 𐍇𐍂𐌹𐍃𐍄𐌿, 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌹 𐌿𐍃𐌼𐌴𐍄𐌹𐍃 𐌹𐍃𐍂𐌰𐌴𐌻𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍃𐍄𐌴𐌹𐍃 𐌲𐌰𐌷𐌰𐌹𐍄𐌴 𐍄𐍂𐌰𐌿𐍃𐍄𐌴𐌹𐍃, 𐍅𐌴𐌽 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐌲(𐌿𐌳𐌰)𐌻𐌰𐌿𐍃𐌰𐌹 𐌹𐌽 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹.',
        13: '𐌹𐌸 𐌽𐌿 𐍃𐌰𐌹, 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌾𐌿𐍃 𐌾𐌿𐌶𐌴𐌹 𐍃𐌹𐌼𐌻𐌴 𐍅𐌴𐍃𐌿𐌸 𐍆𐌰𐌹𐍂𐍂𐌰, 𐍅𐌰𐌿𐍂𐌸𐌿𐌸 𐌽𐌴𐍈𐌰 𐌹𐌽 𐌱𐌻𐍉𐌸𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃. 𐌹𐌸 (𐌽𐌿) 𐍃𐌰𐌹, 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌾𐌿𐍃 𐌾𐌿𐌶𐌴𐌹 𐍃𐌹𐌼(𐌻𐌴) (𐍅)𐌴𐍃𐌿𐌸 𐍆𐌰𐌹𐍂𐍂𐌰, 𐍅𐌰𐌿𐍂𐌸𐌿𐌸 𐌽𐌴𐍈𐌰 𐌹𐌽 𐌱𐌻𐍉𐌸𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.',
        14: '𐍃𐌰 𐌰𐌿𐌺 𐌹𐍃𐍄 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌿𐌽𐍃𐌰𐍂, 𐍃𐌰𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌸𐍉 𐌱𐌰 𐌳𐌿 𐍃𐌰𐌼𐌹𐌽 𐌾𐌰𐌷 𐌼𐌹𐌳𐌲𐌰𐍂𐌳𐌹𐍅𐌰𐌳𐌳𐌾𐌿 𐍆𐌰𐌸𐍉𐍃 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽𐌳𐍃, 𐍃𐌰 𐌰𐌿𐌺 𐌹𐍃𐍄 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌿𐌽𐍃𐌰𐍂, 𐍃𐌰𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌸𐍉 𐌱𐌰 𐌳𐌿 𐍃𐌰𐌼𐌹𐌽 𐌾𐌰𐌷 𐌼𐌹𐌸𐌲𐌰𐍂𐌳𐌰𐍅𐌰𐌳𐌳𐌾𐌿 𐍆𐌰𐌸𐍉𐍃 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽𐌳𐍃,',
        15: '𐍆𐌹𐌾𐌰𐌸𐍅𐌰, 𐌰𐌽𐌰 𐌻𐌴𐌹𐌺𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍅𐌹𐍄𐍉𐌸 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌴 𐌲𐌰𐍂𐌰𐌹𐌳𐌴𐌹𐌽𐌹𐌼 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽𐌳𐍃, 𐌴𐌹 𐌸𐌰𐌽𐍃 𐍄𐍅𐌰𐌽𐍃 𐌲𐌰𐍃𐌺𐍉𐍀𐌹 𐌹𐌽 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌳𐌿 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌽𐌹𐌿𐌾𐌰𐌼𐌼𐌰 𐌼𐌰𐌽𐌽, 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐍃 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹, 𐍆𐌹𐌾𐌰𐌸𐍅𐌰, 𐌰𐌽𐌰 𐌻𐌴𐌹𐌺𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍅𐌹𐍄𐍉𐌸 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌴 𐌲𐌰𐍂𐌰𐌹𐌳𐌴𐌹𐌽𐌹𐌼 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽𐌳𐍃, 𐌴𐌹 𐌸𐌰𐌽𐍃 𐍄𐍅𐌰𐌽𐍃 𐌲𐌰𐍃𐌺𐍉𐍀𐌹 𐌹𐌽 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌳𐌿 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌽𐌹𐌿𐌾𐌰𐌼𐌼𐌰 𐌼𐌰𐌽𐌽, 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽(𐌳𐍃) 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹,',
        16: '𐌾𐌰𐌷 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌳𐌴𐌳𐌹 𐌸𐌰𐌽𐍃 𐌱𐌰𐌽𐍃 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰 𐌲𐌿𐌳𐌰 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌲𐌰𐌽, 𐌰𐍆𐍃𐌻𐌰𐌷𐌰𐌽𐌳𐍃 𐍆𐌹𐌾𐌰𐌸𐍅𐌰 𐌹𐌽 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽. 𐌾𐌰𐌷 𐌲𐌰𐍆𐍂𐌹𐌸𐍉𐌳𐌴𐌳𐌹 𐌸𐌰𐌽𐍃 𐌱𐌰𐌽𐍃 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰 𐌲𐌿𐌳𐌰 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌲𐌰𐌽, 𐌰𐍆𐍃𐌻𐌰𐌷𐌰𐌽𐍃 𐍆𐌹𐌾𐌰𐌸𐍅𐌰 𐌹𐌽 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽.',
        17: '𐌾𐌰𐌷 𐌵𐌹𐌼𐌰𐌽𐌳𐍃 𐍅𐌰𐌹𐌻𐌰𐌼𐌴𐍂𐌹𐌳𐌰 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌹𐌶𐍅𐌹𐍃 𐌾𐌿𐌶𐌴𐌹 𐍆𐌰𐌹𐍂𐍂𐌰 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌸𐌰𐌹𐌼 𐌹𐌶𐌴 𐌽𐌴𐍈𐌰; 𐌾𐌰𐌷 𐌵𐌹𐌼𐌰𐌽𐌳𐍃 𐍅𐌰𐌹𐌻𐌰𐌼𐌴𐍂𐌹𐌳𐌰 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌹𐌶𐍅𐌹𐍃 𐌾𐌿𐌶𐌴𐌹 𐍆𐌰𐌹𐍂𐍂𐌰 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌸𐌰𐌹𐌼 𐌹𐌶𐌴𐌹 𐌽𐌴𐍈𐌰;',
        18: '𐌿𐌽𐍄𐌴 𐌸𐌰𐌹𐍂𐌷 𐌹𐌽𐌰 𐌷𐌰𐌱𐌰𐌼 𐌰𐍄𐌲𐌰𐌲𐌲 𐌱𐌰𐌾𐍉𐌸𐍃 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐌷𐌼𐌹𐌽 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽. 𐌿𐌽𐍄𐌴 𐌸(𐌰)𐌹𐍂𐌷 𐌹𐌽𐌰 𐌷𐌰𐌱𐌰𐌼 𐌰𐍄𐌲𐌰𐌲𐌲 𐌱𐌰𐌾𐍉𐌸𐍃 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐌷𐌼𐌹𐌽 𐌳𐌿 𐌰𐍄𐍄(𐌹𐌽).',
        19: '𐍃𐌰𐌹 𐌽𐌿 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐍃𐍄𐌴𐌹𐍃 𐌾𐌰𐌷 𐌰𐌻𐌾𐌰𐌺𐍉𐌽𐌾𐌰𐌹, 𐌰𐌺 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐌱𐌰𐌿𐍂𐌲𐌾𐌰𐌽𐍃 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌾𐌰𐌷 𐌹𐌽𐌲𐌰𐍂𐌳𐌾𐌰𐌽𐍃 𐌲𐌿𐌳𐌹𐍃, 𐍃𐌰𐌹 𐌽𐌿 𐌾𐌿 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐍃𐍄𐌴𐌹𐍃 (𐌾𐌰𐌷) 𐌰𐌻𐌾𐌰𐌺𐍉𐌽𐌾𐌰𐌹, 𐌰𐌺 𐍃𐌹𐌾𐌿𐌸 𐌲𐌰𐌱𐌰(𐌿𐍂𐌲)𐌾𐌰𐌽𐍃 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌾𐌰𐌷 𐌹𐌽𐌲(𐌰𐍂)𐌳𐌾𐌰𐌽𐍃 𐌲𐌿𐌳𐌹𐍃,',
        20: '𐌰𐌽𐌰𐍄𐌹𐌼𐍂𐌹(𐌳𐌰𐌹).... 𐌰𐌽𐌰𐍄𐌹𐌼𐍂𐌹𐌳𐌰𐌹 𐌰𐌽𐌰 𐌲𐍂𐌿𐌽𐌳𐌿𐍅𐌰𐌳𐌳𐌾𐌰𐌿 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌴 𐌾𐌰𐌷 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌴, 𐌰𐍄 𐍅𐌹𐍃𐌰𐌽𐌳𐌹𐌽 𐌰𐌿𐌷𐌿𐌼𐌹𐍃𐍄𐌹𐌽 𐍅𐌰𐌹𐌷𐍃𐍄𐌰𐍃𐍄𐌰𐌹𐌽𐌰 𐍃𐌹𐌻𐌱𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿,',
        21: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐌻𐌻𐌰 𐌲𐌰𐍄𐌹𐌼𐍂𐌾𐍉 𐌲𐌰𐌲𐌰𐍄𐌹𐌻𐍉𐌳𐌰 𐍅𐌰𐌷𐍃𐌴𐌹𐌸 𐌳𐌿 𐌰𐌻𐌷 𐍅𐌴𐌹𐌷𐌰𐌹 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽,',
        22: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌼𐌹𐌸𐌲𐌰𐍄𐌹𐌼𐍂𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌳𐌿 𐌱𐌰𐌿𐌰𐌹𐌽𐌰𐌹 𐌲𐌿𐌳𐌹𐍃 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽.',
    },
    3: {
        1: '𐌹𐌽 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐌹𐌷𐍄𐌰𐌹𐍃 𐌹𐌺 𐍀𐌰𐍅𐌻𐌿𐍃 𐌱𐌰𐌽𐌳𐌾𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰 𐌸𐌹𐌿𐌳𐍉,',
        2: '𐌾𐌰𐌱𐌰𐌹 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌲𐌲𐌹 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐍃𐍄𐌰𐌹𐍃, 𐍃𐌴𐌹 𐌲𐌹𐌱𐌰𐌽𐌰 𐌹𐍃𐍄 𐌼𐌹𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃;',
        3: '𐌿𐌽𐍄𐌴 𐌱𐌹 𐌰𐌽𐌳𐌷𐌿𐌻𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌺𐌰𐌽𐌽𐌹𐌳𐌰 𐍅𐌰𐍃 𐌼𐌹𐍃 𐍃𐍉 𐍂𐌿𐌽𐌰, 𐍃𐍅𐌴 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐌰 𐌹𐌽 𐌻𐌴𐌹𐍄𐌹𐌻𐌰𐌼𐌼𐌰,',
        4: '𐌳𐌿𐌸𐌸𐌴 𐌴𐌹 𐍃𐌹𐌲𐌲𐍅𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌰𐌲𐌴𐌹𐌸 𐍆𐍂𐌰𐌸𐌾𐌰𐌽 𐍆𐍂𐍉𐌳𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐍂𐌿𐌽𐌰𐌹 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        5: '𐌸𐌰𐍄𐌴𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹𐌼 𐌰𐌻𐌳𐌹𐌼 𐌽𐌹 𐌺𐌿𐌽𐌸 𐍅𐌰𐍃 𐍃𐌿𐌽𐌿𐌼 𐌼𐌰𐌽𐌽𐌴, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌽𐌿 𐌰𐌽𐌳𐌷𐌿𐌻𐌹𐌸 𐌹𐍃𐍄 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌹𐍃 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐌼 𐌾𐌰𐌷 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌿𐌼 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽,',
        6: '𐍅𐌹𐍃𐌰𐌽 𐌸𐌹𐌿𐌳𐍉𐍃 𐌲𐌰𐌰𐍂𐌱𐌾𐌰𐌽𐍃 𐌾𐌰𐌷 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌽𐍃 𐌾𐌰𐌷 𐌲𐌰𐌳𐌰𐌹𐌻𐌰𐌽𐍃 𐌲𐌰𐌷𐌰𐌹𐍄𐌹𐍃 𐌹𐍃 𐌹𐌽 𐍇𐍂(𐌹𐍃)𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌸𐌰𐌹𐍂𐌷 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽,',
        7: '𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐍅𐌰𐍂𐌸 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌹𐌺 𐌱𐌹 𐌲𐌹𐌱𐌰𐌹 𐌰𐌽𐍃𐍄𐌰𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌸𐌹𐌶𐌰𐌹 𐌲𐌹𐌱𐌰𐌽𐍉𐌽 𐌼𐌹𐍃 𐌱𐌹 𐍄𐍉𐌾𐌰 𐌼𐌰𐌷𐍄𐌰𐌹𐍃 𐌹𐍃.',
        8: '𐌼𐌹𐍃, 𐌸𐌰𐌼𐌼𐌰 𐌿𐌽𐌳𐌰𐍂𐌻𐌴𐌹𐌾𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐌸𐌹𐌶𐌴 𐍅𐌴𐌹𐌷𐌰𐌽𐌴, 𐌰𐍄𐌲𐌹𐌱𐌰𐌽𐌰 𐍅𐌰𐍂𐌸 𐌰𐌽𐍃𐍄𐍃 𐍃𐍉, 𐌹𐌽 𐌸𐌹𐌿𐌳𐍉𐌼 𐍅𐌰𐌹𐌻𐌰𐌼𐌴𐍂𐌾𐌰𐌽 𐌸𐍉 𐌿𐌽𐍆𐌰𐌹𐍂𐌻𐌰𐌹𐍃𐍄𐌹𐌳𐍉𐌽 𐌲𐌰𐌱𐌴𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        9: '.... 𐌹𐌽 𐌲𐌿𐌳𐌰 𐌸𐌰𐌼𐌼𐌰 𐌰𐌻𐌻𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌾𐌰𐌽𐌳𐌹𐌽, 𐌾𐌰𐌷 𐌹𐌽𐌻𐌹𐌿𐌷𐍄𐌾𐌰𐌽 𐌰𐌻𐌻𐌰𐌽𐍃, 𐍈𐌹𐌻𐌴𐌹𐌺 𐌸𐌰𐍄𐌰 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌲𐌲𐌹 𐍂𐌿𐌽𐍉𐍃 𐌸𐌹𐌶𐍉𐍃 𐌲𐌰𐍆𐌿𐌻𐌲𐌹𐌽𐍉𐌽𐍃 𐍆𐍂𐌰𐌼 𐌰𐌹𐍅𐌰𐌼 𐌹𐌽 𐌲𐌿𐌳𐌰 𐌸𐌰𐌼𐌼𐌰 𐌰𐌻𐌻𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌾𐌰𐌽𐌳𐌹𐌽,',
        10: '𐌴𐌹 𐌺𐌰𐌽𐌽𐌹𐌸 𐍅𐌴𐍃𐌹 𐌽𐌿 𐍂𐌴𐌹𐌺𐌾𐌰𐌼 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰𐌼 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌼 𐌸𐌰𐌹𐍂𐌷 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽 𐍃𐍉 𐍆𐌹𐌻𐌿𐍆𐌰𐌹𐌷𐍉 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌺𐌰𐌽𐌽𐌹𐌸 𐍅𐌴𐍃𐌹 𐌽𐌿 𐍂𐌴𐌹𐌺𐌾𐌰𐌼 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰𐌼 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌼 𐌸𐌰𐌹𐍂𐌷 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽 𐍃𐍉 𐌼𐌰𐌽𐌰𐌲𐍆𐌰𐌻𐌸𐍉 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹 𐌲𐌿𐌳𐌹𐍃,',
        11: '𐌱𐌹 𐌼𐌿𐌽𐌰 𐌰𐌹𐍅𐌴 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰, 𐌱𐌹 𐌼𐌿𐌽𐌰 𐌰𐌹𐍅𐌴 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰,',
        12: '𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐌱𐌰𐌻𐌸𐌴𐌹𐌽 [𐍆𐍂𐌴𐌹𐌾(𐌷𐌰𐌻𐍃)] 𐌾𐌰𐌷 𐌰𐍄𐌲𐌰𐌲𐌲 𐌹𐌽 𐍄𐍂𐌰𐌿𐌰𐌹𐌽𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐍃. 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌷𐌰𐌱𐌰𐌼 𐌱𐌰𐌻𐌸𐌴𐌹𐌽 𐌾𐌰𐌷 𐌰𐍄𐌲𐌰𐌲𐌲 𐌹𐌽 𐍄𐍂𐌰𐌿𐌰𐌹𐌽𐌰𐌹 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐍃.',
        13: '𐌹𐌽 𐌸𐌹𐌶𐌴 𐌱𐌹𐌳𐌾𐌰, 𐌽𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌿𐍃𐌲𐍂𐌿𐌳𐌾𐌰𐌽𐍃 𐌹𐌽 𐌰𐌲𐌻𐍉𐌼 𐌼𐌴𐌹𐌽𐌰𐌹𐌼 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍅𐌿𐌻𐌸𐌿𐍃 𐌹𐌶𐍅𐌰𐍂. 𐌹𐌽 𐌸𐌹𐌶𐌴 𐌱𐌹𐌳𐌾𐌰, 𐌽𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌿𐍃𐌲𐍂𐌿𐌳𐌾𐌰𐌽𐍃 𐌹𐌽 𐌰𐌲𐌻𐍉𐌼 𐌼𐌴𐌹𐌽𐌰𐌹𐌼 𐍆𐌰𐌿𐍂 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍅𐌿𐌻𐌸𐌿𐍃 𐌹𐌶𐍅𐌰𐍂.',
        14: '𐌹𐌽 𐌸𐌹𐍃 𐌱𐌹𐌿𐌲𐌰 𐌺𐌽𐌹𐍅𐌰 𐌼𐌴𐌹𐌽𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌹𐌽 𐌸𐌹𐍃 𐌱𐌹𐌿𐌲𐌰 𐌺𐌽𐌹𐍅𐌰 𐌼𐌴𐌹𐌽𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        15: '𐌿𐍃 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐌻𐌻 𐍆𐌰𐌳𐍂𐌴𐌹𐌽𐌹𐍃 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰 𐌾𐌰𐌷 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌽𐌰𐌼𐌽𐌾𐌰𐌳𐌰, 𐌿𐍃 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐌻𐌻 𐍆𐌰𐌳𐍂𐌴𐌹𐌽𐌹𐍃 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰 𐌾𐌰𐌷 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹 𐌽𐌰𐌼𐌽𐌾𐌰𐌳𐌰,',
        16: '𐌴𐌹 𐌲𐌹𐌱𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌱𐌹 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐍃𐌴𐌹𐌽𐌹𐍃 𐌼𐌰𐌷𐍄𐌰𐌹 𐌹𐌽𐍃𐍅𐌹𐌽𐌸𐌾𐌰𐌽 𐌸𐌰𐌹𐍂𐌷 𐌰𐌷𐌼𐌰𐌽 𐍃𐌴𐌹𐌽𐌰𐌽𐌰 𐌹𐌽𐌽𐌿𐌼𐌰𐌽 𐌼𐌰𐌽𐌽𐌰𐌽, 𐌴𐌹 𐌲𐌹𐌱𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌱𐌹 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸𐌰𐌿𐍃 𐍃𐌴𐌹𐌽𐌹𐍃 𐌼𐌰𐌷𐍄𐌰𐌹 𐌲𐌰𐍃𐍅𐌹𐌽𐌸𐌽𐌰𐌽 𐌸𐌰𐌹𐍂𐌷 𐌰𐌷𐌼𐌰𐌽 𐍃𐌴𐌹𐌽𐌰𐌽𐌰 𐌹𐌽 𐌹𐌽𐌽𐌿𐌼𐌰𐌽 𐌼𐌰𐌽𐌽𐌰𐌽,',
        17: '𐌱𐌰𐌿𐌰𐌽 𐍇𐍂𐌹𐍃𐍄𐌿 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼, 𐌱𐌰𐌿𐌰𐌽 𐍇𐍂𐌹𐍃𐍄𐌿 𐌸𐌰𐌹𐍂𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼,',
        18: '𐌴𐌹 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐍃𐌿𐌻𐌹𐌳𐌰𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐌲𐌰𐍆𐌰𐌷𐌰𐌽 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐍈𐌰 𐍃𐌹𐌾𐌰𐌹 𐌱𐍂𐌰𐌹𐌳𐌴𐌹 𐌾𐌰𐌻~𐌻𐌰𐌲𐌲𐌴𐌹 𐌾𐌰𐌷 𐌷𐌰𐌿𐌷𐌴𐌹 𐌾𐌰𐌷 𐌳(𐌹𐌿𐍀𐌴)𐌹; 𐌴𐌹 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐍃𐌿𐌻𐌹𐌳𐌰𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐌲𐌰𐍆𐌰𐌷𐌰𐌽 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐍈𐌰 𐍃𐌹𐌾𐌰𐌹 𐌱𐍂𐌰𐌹𐌳𐌴𐌹 𐌾𐌰𐌷 𐌻𐌰𐌲𐌲𐌴𐌹 𐌾𐌰𐌷 𐌷𐌰𐌿𐌷𐌴𐌹 𐌾𐌰𐌷 𐌳𐌹𐌿𐍀𐌴𐌹;',
        19: '𐌺𐌿𐌽𐌰𐌽 𐌸𐍉 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌼𐌹𐌺𐌹𐌻𐍉𐌽 𐌸𐌹𐍃 𐌺𐌿𐌽𐌸𐌾𐌹𐍃 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌴𐌹 𐍆𐌿𐌻𐌽𐌰𐌹𐌸 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐍆𐌿𐌻𐌻𐍉𐌽 𐌲𐌿𐌳𐌹𐍃. 𐌺𐌿𐌽𐌽𐌰𐌽 𐌸𐍉 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌼𐌹𐌺𐌹𐌻𐍉𐌽 𐌸𐌹𐍃 𐌺𐌿𐌽𐌸𐌾𐌹𐍃 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌴𐌹 𐍆𐌿𐌻𐌻𐌽𐌰𐌹𐌸 𐌳𐌿 𐌰𐌻𐌻𐌰𐌹 𐍆𐌿𐌻𐌻𐍉𐌽 𐌲𐌿𐌳𐌹𐍃.',
        20: '𐌰𐌸𐌸𐌰𐌽 𐌸𐌰𐌼𐌼𐌰 𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌹𐌽 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻 𐍄𐌰𐌿𐌾𐌰𐌽 𐌼𐌰𐌹𐌶𐍉 [𐌲𐌹𐌱𐌰𐌽] 𐌸𐌰𐌿 𐌱𐌹𐌳𐌾𐌰𐌼 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐍂𐌰𐌸𐌾𐌰𐌼 𐌱𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐌸𐌹𐌶𐌰𐌹 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌴𐌹𐌽 𐌹𐌽 𐌿𐌽𐍃𐌹𐍃, 𐌰𐌸𐌸𐌰𐌽 𐌸𐌰𐌼𐌼𐌰 𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌹𐌽 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻 𐍄𐌰𐌿𐌾𐌰𐌽 𐌼𐌰𐌹𐌶𐍉 𐌸𐌰𐌿 𐌱𐌹𐌳𐌾𐌰𐌼 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐍂𐌰𐌸𐌾𐌰𐌼 𐌱𐌹 𐌼𐌰𐌷𐍄𐌰𐌹 𐌸𐌹𐌶𐌰𐌹 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌴𐌹𐌽 𐌹𐌽 𐌿𐌽𐍃,',
        21: '𐌹𐌼𐌼𐌿𐌷 𐍅𐌿𐌻𐌸𐌿𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌾𐌰𐌷 𐌰𐌹𐌺𐌺𐌻𐌴𐍃 𐌹𐌽 𐌰𐌻𐌻𐍉𐍃 𐌰𐌻𐌳𐌹𐌽𐍃 𐌰𐌹𐍅𐌴, 𐌰𐌼𐌴𐌽. 𐌹𐌼𐌼𐌰 𐍅𐌿𐌻𐌸𐌿𐍃 𐌹𐌽 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌹𐌽 𐌰𐌻𐌻𐍉𐍃 𐌰𐌻𐌳𐌹𐌽𐍃 𐌰𐌹𐍅𐌴, 𐌰𐌼𐌴𐌽.',
    },
    4: {
        1: '𐌱𐌹𐌳𐌾𐌰 𐌽𐌿 𐌹𐌶𐍅𐌹𐍃 𐌹𐌺 𐌱𐌰𐌽𐌳𐌾𐌰 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐍅𐌰𐌹𐍂𐌸𐌰𐌱𐌰 𐌲𐌰𐌲𐌲𐌰𐌽 𐌸𐌹𐌶𐍉𐍃 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰𐌹 𐍃𐌹𐌿𐌸, 𐌱𐌹𐌳𐌾𐌰 𐌽𐌿 𐌹𐌶𐍅𐌹𐍃 𐌹𐌺 𐌱𐌰𐌽𐌳𐌾𐌰 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐍅𐌰𐌹𐍂𐌸𐌰𐌱𐌰 𐌲𐌰𐌲𐌲𐌰𐌽 𐌸𐌹𐌶𐍉𐍃 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸,',
        2: '𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌿𐌽𐌴𐌹𐌽𐌰𐌹 𐌾𐌰𐌷 𐌵𐌰𐌹𐍂𐍂𐌴𐌹𐌽, 𐌼𐌹𐌸 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌰𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹, 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹 𐌷𐌰𐌿𐌽𐌴𐌹𐌽𐌰𐌹 𐌾𐌰𐌷 𐌵𐌰𐌹𐍂𐍂𐌴𐌹𐌽, 𐌼𐌹𐌸 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌰𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹,',
        3: '𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍆𐌰𐍃𐍄𐌰𐌽 𐌰𐌹𐌽𐌰𐌼𐌿𐌽𐌳𐌹𐌸𐌰 𐌰𐌷𐌼𐌹𐌽𐍃 𐌹𐌽 𐌲𐌰𐌱𐌿𐌽𐌳𐌾𐌰𐌹 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌴𐌹𐍃. 𐌿𐍃𐌳𐌰𐌿𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍆𐌰𐍃𐍄𐌰𐌽 𐌰𐌹𐌽𐌰𐌼𐌿𐌽𐌳𐌹𐌸𐌰 𐌰𐌷𐌼𐌹𐌽𐍃 𐌹𐌽 𐌲𐌰𐌱𐌿𐌽𐌳𐌾𐌰𐌹 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌴𐌹𐍃.',
        4: '𐌰𐌹𐌽 𐌻𐌴𐌹𐌺 𐌾𐌰𐌷 𐌰𐌹𐌽𐍃 𐌰𐌷𐌼𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐍄𐌻𐌰𐌸𐍉𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌰𐌹𐌽𐌰 𐍅𐌴𐌽 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃. 𐌰𐌹𐌽 𐌻𐌴𐌹𐌺 𐌾𐌰𐌷 𐌰𐌹𐌽𐍃 𐌰𐌷𐌼𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐍄𐌻𐌰𐌸𐍉𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌰𐌹𐌽𐌰 𐍅𐌴𐌽 𐌻𐌰𐌸𐍉𐌽𐌰𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃.',
        5: '𐌰𐌹𐌽𐍃 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌰𐌹𐌽𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐍃, 𐌰𐌹𐌽𐌰 𐌳𐌰𐌿𐍀𐌴𐌹𐌽𐍃, 𐌰𐌹𐌽𐍃 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌰𐌹𐌽𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐍃, 𐌰𐌹𐌽𐌰 𐌳𐌰𐌿𐍀𐌴𐌹𐌽𐍃,',
        6: '𐌰𐌹𐌽𐍃 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌰𐌻𐌻𐌰𐌹𐌶𐌴, 𐍃𐌰𐌴𐌹 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰𐌹𐌼 𐌾𐌰𐌷 𐌰𐌽𐌳 𐌰𐌻𐌻𐌰𐌽𐍃 𐌾𐌰𐌷 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌿𐌽𐍃. 𐌰𐌹𐌽𐍃 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌰𐌻𐌻𐌰𐌹𐌶𐌴....',
        7: '𐌹𐌸 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌰𐌼𐌼𐌴𐌷 𐌿𐌽𐍃𐌰𐍂𐌰 𐌰𐍄𐌲𐌹𐌱𐌰𐌽𐌰 𐌹𐍃𐍄 𐌰𐌽𐍃𐍄𐍃 𐌱𐌹 𐌼𐌹𐍄𐌰𐌸 𐌲𐌹𐌱𐍉𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃;',
        8: '𐌹𐌽 𐌸𐌹𐌶𐌴𐌹 𐌵𐌹𐌸𐌹𐌸: 𐌿𐍃𐍃𐍄𐌴𐌹𐌲𐌰𐌽𐌳𐍃 𐌹𐌽 𐌷𐌰𐌿𐌷𐌹𐌸𐌰 𐌿𐍃𐌷𐌰𐌽𐌸 𐌷𐌿𐌽𐌸 𐌾𐌰𐌷 𐌰𐍄𐌿𐌷𐌲𐌰𐍆 𐌲𐌹𐌱𐍉𐍃 𐌼𐌰𐌽𐌽𐌰𐌼.',
        9: '𐌸𐌰𐍄𐌿𐌸~𐌸𐌰𐌽 𐌿𐍃𐍃𐍄𐌰𐌹𐌲, 𐍈𐌰 𐌹𐍃𐍄, 𐌽𐌹𐌱𐌰 𐌸𐌰𐍄𐌴𐌹 𐌾𐌰𐌷 𐌰𐍄𐍃𐍄𐌰𐌹𐌲 𐍆𐌰𐌿𐍂𐌸𐌹𐍃 𐌹𐌽 𐌿𐌽𐌳𐌰𐍂[𐌰]𐌹𐍃𐍄𐍉 𐌰𐌹𐍂𐌸𐍉𐍃?',
        10: '𐍃𐌰𐌴𐌹 𐌰𐍄𐍃𐍄𐌰𐌹𐌲, 𐍃𐌰 𐌹𐍃𐍄 𐌾𐌰𐌷 𐍃𐌰𐌴𐌹 𐌿𐍃𐍃𐍄𐌰𐌹𐌲 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰𐌽𐍃 𐌷𐌹𐌼𐌹𐌽𐌰𐌽𐍃, 𐌴𐌹 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌳𐌴𐌳𐌹 𐌰𐌻𐌻𐌰𐍄𐌰.',
        11: '𐌾𐌰𐌷 𐍃𐌹𐌻𐌱𐌰 𐌲𐌰𐍆 𐍃𐌿𐌼𐌰𐌽𐍃 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻(𐌿)𐌽𐍃, 𐍃𐌿𐌼𐌰𐌽𐌶𐌿𐌸~𐌸𐌰𐌽 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌿𐌽𐍃, 𐍃𐌿𐌼𐌰𐌽𐍃𐌿𐌸~𐌸𐌰𐌽 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌹𐍃𐍄𐌰𐌽𐍃, 𐍃𐌿𐌼𐌰𐌽𐍃𐌿𐌸~𐌸𐌰𐌽 𐌷𐌰𐌹𐍂𐌳𐌾𐌰𐌽𐍃 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌰𐍂𐌾𐌰𐌽𐍃,',
        12: '𐌳𐌿 𐌿𐍃𐍄𐌰𐌿𐌷𐍄𐌰𐌹 𐍅𐌴𐌹𐌷𐌰𐌹𐌶𐌴 𐌳𐌿 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐌾𐌹𐍃, 𐌳𐌿 𐍄𐌹𐌼𐍂𐌴𐌹𐌽𐌰𐌹 𐌻𐌴𐌹𐌺𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        13: '𐌿𐌽𐍄𐌴 𐌲𐌰𐍂𐌹𐌽𐌽𐌰𐌹𐌼𐌰 𐌰𐌻𐌻𐌰𐌹 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌿𐌽𐌳𐌹𐌸𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃 𐌾𐌰𐌷 𐌿𐍆𐌺𐌿𐌽𐌸𐌾𐌹𐍃 𐍃𐌿𐌽𐌿𐍃 𐌲𐌿𐌳𐌹𐍃, 𐌳𐌿 𐍅𐌰𐌹𐍂𐌰 𐍆𐌿𐌻𐌻𐌰𐌼𐌼𐌰, 𐌹𐌽 𐌼𐌹𐍄𐌰𐌸 𐍅𐌰𐌷𐍃𐍄𐌰𐌿𐍃 𐍆𐌿𐌻𐌻𐍉𐌽𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,',
        14: '𐌴𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰 𐌽𐌹𐌿𐌺𐌻𐌰𐌷𐌰𐌹 𐌿𐍃𐍅𐌰𐌲𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌿𐍃𐍅𐌰𐌻𐌿𐌲𐌹𐌳𐌰𐌹 𐍅𐌹𐌽𐌳𐌰 𐍈𐌰𐌼𐌼𐌴𐌷 𐌻𐌰𐌹𐍃𐌴𐌹𐌽𐌰𐌹𐍃, 𐌻𐌹𐌿𐍄𐌴𐌹𐌽 𐌼𐌰𐌽𐌽𐌴, 𐌹𐌽 𐍆𐌹𐌻𐌿𐌳𐌴𐌹𐍃𐌴𐌹𐌽 𐌳𐌿 𐌻𐌹𐍃𐍄𐌴𐌹𐌲𐍉𐌽 𐌿𐍃𐍅𐌰𐌽𐌳𐌾𐌰𐌹 𐌰𐌹𐍂𐌶𐌴𐌹𐌽𐍃,',
        15: '𐌹𐌸 𐍃𐌿𐌽𐌾𐌰 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹 𐍅𐌰𐌷𐍃𐌾𐌰𐌹𐌼𐌰 𐌹𐌽 𐌹𐌽𐌰 𐌸𐍉 𐌰𐌻𐌻𐌰, 𐌹𐌶𐌴 𐌹𐍃𐍄 𐌷𐌰𐌿𐌱𐌹𐌸, 𐍇𐍂𐌹𐍃𐍄𐌿𐍃,',
        16: '𐌿𐍃 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐌻𐌻 𐌻𐌴𐌹𐌺 𐌲𐌰𐌲𐌰𐍄𐌹𐌻𐍉𐌸 𐌲𐌰𐌲𐌰𐌷𐌰𐍆𐍄𐌹𐌸 𐌸𐌰𐌹𐍂𐌷 𐌰𐌻𐌻𐍉𐍃 𐌲𐌰𐍅𐌹𐍃𐍃𐌹𐌽𐍃 𐌰𐌽𐌳𐍃𐍄𐌰𐌻𐌳𐌹𐍃, 𐌱𐌹 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌹𐌽 𐌼𐌹𐍄𐌰𐌸 𐌰𐌽𐌰 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐍉𐌷 𐍆𐌴𐍂𐍉, 𐌿𐍃𐍅𐌰𐌷𐍃𐍄 𐌻𐌴𐌹𐌺𐌹𐍃 𐍄𐌰𐌿𐌾𐌹𐌸 𐌳𐌿 𐍄𐌹𐌼𐍂𐌴𐌹𐌽𐌰𐌹 𐍃𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹.',
        17: '𐌸𐌰𐍄𐌰 𐌽𐌿 𐌵𐌹𐌸𐌰 𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌴𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌲𐌰𐌲𐌲𐌰𐌹𐌸, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌰𐌽𐌸𐌰𐍂𐍉𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐌲𐌰𐌲𐌲𐌰𐌽𐌳 𐌹𐌽 𐌿𐍃𐍅𐌹𐍃𐍃𐌾𐌰 𐌷𐌿𐌲𐌹𐍃 𐍃𐌴𐌹𐌽𐌹𐍃, 𐌸𐌰𐍄𐌰 𐌽𐌿 𐌵𐌹𐌸𐌰 𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉(𐌳)𐌾𐌰 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌴𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌲𐌰𐌲𐌲𐌰𐌹𐌸, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌰𐌽𐌸𐌰𐍂𐍉𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐌲𐌰𐌲𐌲𐌰𐌽𐌳 𐌹𐌽 𐌿𐍃𐍅𐌹𐍃𐍃𐌾𐌰 𐌷𐌿𐌲𐌹𐍃 𐍃𐌴𐌹𐌽𐌹𐍃,',
        18: '𐍂𐌹𐌵𐌹𐌶𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌷𐌿𐌲𐌳𐌰𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃, 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌹 𐌻𐌹𐌱𐌰𐌹𐌽𐌰𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌹𐌽 𐌿𐌽𐍅𐌹𐍄𐌾𐌹𐍃 𐌸𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌹𐌽𐍃 𐌹𐌽 𐌹𐌼, 𐌹𐌽 𐌳𐌰𐌿𐌱𐌹𐌸𐍉𐍃 𐌷𐌰𐌹𐍂𐍄𐌰𐌽𐌴 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐌴, 𐍂𐌹𐌵𐌹𐌶𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌷𐌿𐌲𐌳𐌰𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃, 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌹 𐌻𐌹𐌱𐌰𐌹𐌽𐌰𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌹𐌽 𐌿𐌽𐍅𐌹𐍄𐌾𐌹𐍃 𐌸𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌹𐌽𐍃 𐌹𐌽 𐌹𐌼, 𐌹𐌽 𐌳𐌰𐌿𐌱𐌹𐌸𐍉𐍃 𐌷𐌰𐌹𐍂𐍄𐌰𐌽𐌴 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐌴,',
        19: '𐌸𐌰𐌹𐌴𐌹 𐌿𐍃𐍅𐌴𐌽𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌸𐌰𐌽𐌰𐌹 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐌰𐍄𐌲𐌴𐌱𐌿𐌽 𐌰𐌲𐌻𐌰𐌹𐍄𐌴𐌹𐌽 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴𐌹𐌽 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌹𐌸𐍉𐍃 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃, 𐌹𐌽 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐌴𐌹𐌽. 𐌸𐌰𐌹𐌴𐌹 𐌿𐍃𐍅𐌴𐌽𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌸𐌰𐌽𐌰𐌹 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐌰𐍄𐌲𐌴𐌱𐌿𐌽 𐌰𐌲𐌻𐌰𐌹𐍄𐌴𐌹𐌽 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴𐌹𐌽 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌹𐌸𐍉𐍃 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃, 𐌹𐌽 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐌴𐌹𐌽.',
        20: '𐌹𐌸 𐌾𐌿𐍃 𐌽𐌹 𐍃𐍅𐌰 𐌲𐌰𐌽𐌴𐌼𐌿𐌸 𐍇𐍂𐌹𐍃𐍄𐌿, 𐌹𐌸 𐌾𐌿𐍃 𐌽𐌹 𐍃𐍅𐌰 𐌲𐌰𐌽𐌴𐌼𐌿𐌸 𐍇𐍂𐌹𐍃𐍄𐌿,',
        21: '𐌾𐌰𐌱𐌰𐌹 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌹𐌽𐌰 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸 𐌾𐌰𐌷 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌿𐍃𐌻𐌰𐌹𐍃𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐌰 𐌹𐌽 𐌹𐌴𐍃𐌿, 𐌾𐌰𐌱𐌰𐌹 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌹𐌽𐌰 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸 𐌾𐌰𐌷 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌿𐍃𐌻𐌰𐌹𐍃𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐌰 𐌹𐌽 𐌹𐌴𐍃𐌿,',
        22: '𐌴𐌹 𐌰𐍆𐌻𐌰𐌲𐌾𐌰𐌹𐌸 𐌾𐌿𐍃 𐌱𐌹 𐍆𐍂𐌿𐌼𐌹𐌽 𐌿𐍃𐌼𐌴𐍄𐌰 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐌽𐌾𐌰𐌽 𐌼𐌰𐌽𐌽𐌰𐌽 𐌸𐌰𐌽𐌰 𐍂𐌹𐌿𐍂𐌾𐌰𐌽 𐌱𐌹 𐌻𐌿𐍃𐍄𐌿𐌼 𐌰𐍆𐌼𐌰𐍂𐌶𐌴𐌹𐌽𐌰𐌹𐍃. 𐌴𐌹 𐌰𐍆𐌻𐌰𐌲𐌾𐌰𐌹𐌸 𐌾𐌿𐍃 𐌱𐌹 𐍆𐍂𐌿𐌼𐌹𐌽 𐌿𐍃𐌼𐌴𐍄𐌰 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐌽𐌾𐌰𐌽 𐌼𐌰𐌽𐌽𐌰𐌽 𐌸𐌰𐌽𐌰 𐍂𐌹𐌿𐍂𐌾𐌰𐌽 𐌱𐌹 𐌻𐌿𐍃𐍄𐌿𐌼 𐌰𐍆𐌼𐌰𐍂𐌶𐌴𐌹𐌽𐌰𐌹𐍃.',
        23: '𐌰𐌽𐌿𐌸~𐌸𐌰𐌽~𐌽𐌹𐌿𐌾𐌰𐌹𐌸 𐌰𐌷𐌼𐌹𐌽 𐍆𐍂𐌰𐌸𐌾𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃, 𐌰𐌽𐌿𐌸~𐌸𐌰𐌽~𐌽𐌹𐌿𐌾𐌰𐌹𐌸 (𐌰)𐌷𐌼𐌹𐌽 𐍆𐍂𐌰𐌸𐌾𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃,',
        24: '𐌾𐌰𐌲~𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌸𐌰𐌼𐌼𐌰 𐌽𐌹𐌿𐌾𐌹𐌽 𐌼𐌰𐌽𐌽 𐌸𐌰𐌼𐌼𐌰 𐌱𐌹 𐌲𐌿𐌳𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌹𐌽 𐌹𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌾𐌰𐌷 𐍅𐌴𐌹𐌷𐌹𐌸𐌰𐌹 𐍃𐌿𐌽𐌾𐍉𐍃. 𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌸𐌰𐌼𐌼𐌰 𐌽𐌹𐌿𐌾𐌹𐌽 𐌼𐌰𐌽𐌽 𐌸𐌰𐌼𐌼𐌰 𐌱𐌹 𐌲𐌿𐌳𐌰 𐌲𐌰𐍃𐌺𐌰𐍀𐌰𐌽𐌹𐌽 𐌹𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌾𐌰𐌷 𐍅𐌴𐌹𐌷𐌹𐌸𐌰𐌹 𐍃𐌿𐌽𐌾𐍉𐍃.',
        25: '𐌹𐌽 𐌸𐌹𐌶𐌴𐌹 𐌰𐍆𐌻𐌰𐌲𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌻𐌹𐌿𐌲𐌽 𐍂𐍉𐌳𐌾𐌰𐌹𐌸 𐍃𐌿𐌽𐌾𐌰 𐍈𐌰𐍂𐌾𐌹𐌶𐌿𐌷 𐌼𐌹𐌸 𐌽𐌴𐍈𐌿𐌽𐌳𐌾𐌹𐌽 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌿𐌽𐍄𐌴 𐍃𐌹𐌾𐌿𐌼 𐌰𐌽𐌸𐌰𐍂 𐌰𐌽𐌸𐌰𐍂𐌹𐍃 𐌻𐌹𐌸𐌿𐍃. 𐌹𐌽 𐌸𐌹𐌶𐌴𐌹 𐌰𐍆𐌻𐌰𐌲𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌻𐌹𐌿𐌲𐌽 𐍂𐍉𐌳𐌾𐌰𐌹𐌸 𐍃𐌿𐌽𐌾𐌰 𐍈𐌰𐍂𐌾𐌹𐌶𐌿𐌷 𐌼𐌹𐌸 𐌽𐌴𐍈𐌿𐌽𐌳𐌾𐌹𐌽 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌿𐌽𐍄𐌴 𐍃𐌹𐌾𐌿𐌸 𐌰𐌽𐌸𐌰𐍂 𐌰𐌽𐌸𐌰𐍂𐌹𐍃 𐌻𐌹𐌸𐌿𐍃.',
        26: '𐌸𐍅𐌰𐌹𐍂𐌷𐌰𐌹𐌸~𐌸𐌰𐌽 𐍃𐌹𐌾𐌰𐌹𐌸 𐌾𐌰𐌷 𐌽𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌹𐌸, 𐍃𐌿𐌽𐌽𐍉 𐌽𐌹 𐌳𐌹𐍃𐍃𐌹𐌲𐌵𐌰𐌹 𐌰𐌽𐌰 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰. 𐌸𐍅𐌰𐌹𐍂𐌷𐌰𐌹𐌸~𐌸𐌰𐌽 𐍃𐌹𐌾𐌰𐌹𐌸 𐌾𐌰𐌷 𐌽𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌹𐌸, 𐍃𐌿𐌽𐌽𐍉 𐌽𐌹 𐌳𐌹𐍃𐌹𐌲𐌲𐌵𐌰𐌹 𐌰𐌽𐌰 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰.',
        27: '𐌽𐌹 𐌲𐌹𐌱𐌹𐌸 𐍃𐍄𐌰𐌸 𐌿𐌽𐌷𐌿𐌻𐌸𐌹𐌽. 𐌽𐌹𐌷 𐌲𐌹𐌱𐌰𐌹𐌸 𐍃𐍄𐌰𐌸 𐌿𐌽𐌷𐌿𐌻𐌸𐌹𐌽.',
        28: '𐍃𐌰𐌴𐌹 𐌷𐌻𐌴𐍆𐌹, 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌷𐌻𐌹𐍆𐌰𐌹, 𐌹𐌸 𐌼𐌰𐌹𐍃 𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰𐌹, 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐍃 𐍃𐍅𐌴𐍃𐌰𐌹𐌼 𐌷𐌰𐌽𐌳𐌿𐌼 𐌸𐌹𐌿𐌸, 𐌴𐌹 𐌷𐌰𐌱𐌰𐌹 𐌳𐌰𐌹𐌻𐌾𐌰𐌽 𐌸𐌰𐌿𐍂𐌱𐌰𐌽𐌳𐌹𐌽. 𐍃𐌰𐌴𐌹 𐌷𐌻𐌴𐍆𐌹, 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌷𐌻𐌹𐍆𐌰𐌹, 𐌰𐌺 𐌼𐌰𐌹𐍃 𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰𐌹, 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐍃 𐍃𐍅𐌴𐍃𐌰𐌹𐌼 𐌷𐌰𐌽𐌳𐌿𐌼 𐌸𐌹𐌿𐌸, 𐌴𐌹 𐌷𐌰𐌱𐌰𐌹 𐌳𐌰𐌹𐌻𐌾𐌰𐌽 𐌸𐌰𐌿𐍂𐌱𐌰𐌽𐌳𐌹𐌽.',
        29: '𐌰𐌹𐌽𐌷𐌿𐌽 𐍅𐌰𐌿𐍂𐌳𐌴 𐌿𐌱𐌹𐌻𐌰𐌹𐌶𐌴 𐌿𐍃 𐌼𐌿𐌽𐌸𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐌽𐌹 𐌿𐍃𐌲𐌰𐌲𐌲𐌰𐌹, 𐌰𐌺 𐌸𐌰𐍄𐌴𐌹 𐌲𐍉𐌸 𐍃𐌹𐌾𐌰𐌹 𐌳𐌿 𐍄𐌹𐌼𐍂𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌴𐌹 𐌲𐌹𐌱𐌰𐌹 𐌰𐌽𐍃𐍄 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌼. 𐌰𐌹𐌽𐌷𐌿𐌽 𐍅𐌰𐌿𐍂𐌳𐌴 𐌿𐌱𐌹𐌻𐌰𐌹𐌶𐌴 𐌿𐍃 𐌼𐌿𐌽𐌸𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐌽𐌹 𐌿𐍃𐌲𐌰𐌲𐌲𐌰𐌹, 𐌰𐌺 𐌸𐌰𐍄𐌴𐌹 𐌲𐍉𐌸 𐍃𐌹𐌾𐌰𐌹 𐌳𐌿 𐍄𐌹𐌼𐍂𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌴𐌹 𐌲𐌹𐌱𐌰𐌹 𐌰𐌽𐍃𐍄 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌼.',
        30: '𐌾𐌰𐌷 𐌽𐌹 𐌲𐌰𐌿𐍂𐌾𐌰𐌹𐌸 𐌸𐌰𐌽𐌰 𐍅𐌴𐌹𐌷𐌰𐌽 𐌰𐌷𐌼𐌰𐌽 𐌲𐌿𐌳𐌹𐍃, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌲𐌰𐍃𐌹𐌲𐌻𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌳𐌰𐌲𐌰 𐌿𐍃𐌻𐌰𐌿𐍃𐌴𐌹𐌽𐌰𐌹𐍃. 𐌾𐌰𐌷 𐌽𐌹 𐌲𐌰𐌿𐍂𐌾𐌰𐌹𐌸 𐌸𐌰𐌽𐌰 𐍅𐌴𐌹𐌷𐌰𐌽 𐌰𐌷𐌼𐌰𐌽 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐌼𐌼𐌴𐌹 𐌲𐌰𐍃𐌹𐌲𐌻𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌳𐌰𐌲𐌰 𐌿𐍃𐌻𐌰𐌿𐍃𐌴𐌹𐌽𐌰𐌹𐍃.',
        31: '𐌰𐌻𐌻𐌰 𐌱𐌰𐌹𐍄𐍂𐌴𐌹 𐌾𐌰𐌷 𐌷𐌰𐍄𐌹𐍃 𐌾𐌰𐌷 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹 𐌾𐌰𐌷 𐌷𐍂𐍉𐍀𐍃 𐌾𐌰𐌷 𐍅𐌰𐌾𐌰𐌼𐌴𐍂𐌴𐌹𐌽𐍃 𐌰𐍆𐍅𐌰𐌹𐍂𐍀𐌰𐌹𐌳𐌰𐌿 𐌰𐍆 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽. 𐌰𐌻𐌻𐌰 𐌱𐌰𐌹𐍄𐍂𐌴𐌹 𐌾𐌰𐌷 𐌷𐌰𐍄𐌹𐍃 𐌾𐌰𐌷 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹 𐌾𐌰𐌷 𐌷𐍂𐍉𐍀𐍃 𐌾𐌰𐌷 𐍅𐌰𐌾𐌰𐌼𐌴𐍂𐌴𐌹𐌽𐍃 𐌰𐍆𐍅𐌰𐌹𐍂𐍀𐌰𐌹𐌳𐌰𐌿 𐌰𐍆 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽.',
        32: '𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌳𐌿𐌷 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐍃𐌴𐌻𐌾𐌰𐌹, 𐌰𐍂𐌼𐌰𐌷𐌰𐌹𐍂𐍄𐌰𐌹, 𐍆𐍂𐌰𐌲𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌿𐌸 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍆𐍂𐌰𐌲𐌰𐍆 𐌹𐌶𐍅𐌹𐍃. 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌳𐌿𐌷 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐍃𐌴𐌻𐌾𐌰𐌹, 𐌰𐍂𐌼𐌰𐌷𐌰𐌹𐍂𐍄𐌰𐌹, 𐍆𐍂𐌰𐌲𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌿𐌸 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍆𐍂𐌰𐌲𐌰𐍆 𐌹𐌶𐍅𐌹𐍃.',
    },
    5: {
        1: '𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌽𐌿 𐌲𐌰𐌻𐌴𐌹𐌺𐍉𐌽𐌳𐌰𐌽𐍃 𐌲𐌿𐌳𐌰 𐍃𐍅𐌴 𐌱𐌰𐍂𐌽𐌰 𐌻𐌹𐌿𐌱𐌰 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌽𐌿 𐌲𐌰𐌻𐌴𐌹𐌺𐍉𐌽𐌳𐌰𐌽𐍃 𐌲𐌿𐌳(𐌰) 𐍃𐍅𐌴 𐌱𐌰𐍂𐌽𐌰 𐌻𐌹𐌿𐌱𐌰',
        2: '𐌾𐌰𐌷 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐌹𐌽 𐍆𐍂𐌹𐌾𐌰𐌸𐍅𐌰𐌹, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌿𐌽𐍃 𐌾𐌰𐌷 𐌰𐍄𐌲𐌰𐍆 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐍆𐌰𐌿𐍂 𐌿𐌽𐍃 𐌷𐌿𐌽𐍃𐌻 𐌾𐌰𐌷 𐍃𐌰𐌿𐌸 𐌲𐌿𐌳𐌰 𐌳𐌿 𐌳𐌰𐌿𐌽𐌰𐌹 𐍅𐍉𐌸𐌾𐌰𐌹. 𐌾𐌰𐌷 𐌲𐌰𐌲𐌲𐌰(𐌹𐌸) 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿(𐍃) 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌿𐌽𐍃 𐌾𐌰𐌷 𐌰𐍄𐌲𐌰𐍆 𐍃𐌹(𐌺) 𐍃𐌹(𐌻)𐌱𐌰𐌽 𐍆𐌰𐌿𐍂 𐌿𐌽𐍃 𐌷𐌿𐌽𐍃𐌻 𐌾𐌰𐌷 𐍃𐌰𐌿𐌸 𐌲𐌿𐌳𐌰 𐌳𐌿 𐌳𐌰𐌿𐌽𐌰𐌹 𐍅𐍉𐌸𐌾𐌰𐌹.',
        3: '𐌰𐌸𐌸𐌰𐌽 𐌷𐍉𐍂𐌹𐌽𐌰𐍃𐍃𐌿𐍃 𐌾𐌰𐌷 𐌰𐌻𐌻𐍉𐍃 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌹𐌸𐍉𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐌴𐌹 𐌽𐌹𐌷 𐌽𐌰𐌼𐌽(𐌾𐌰𐌹𐌳𐌰𐌿).... 𐌰𐌸𐌸𐌰𐌽 𐌷𐍉𐍂𐌹𐌽𐌰𐍃𐍃𐌿𐍃 𐌾𐌰𐌷 𐌰𐌻𐌻𐍉𐍃 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌹𐌸𐍉𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐌴𐌹 𐌽𐌹𐌷 𐌽𐌰𐌼𐌽𐌾𐌰𐌹𐌳𐌰𐌿 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌳𐍉𐌱 𐌹𐍃𐍄 𐍅𐌴𐌹𐌷𐌰𐌹𐌼,',
        4: '𐌰𐌹𐌸𐌸𐌰𐌿 𐌳𐍅𐌰𐌻𐌰(𐍅𐌰)𐌿𐍂𐌳𐌴𐌹 𐌰𐌹𐌸𐌸𐌰𐌿 𐍃𐌰𐌻𐌳𐍂𐌰, 𐌸𐍉𐌴𐌹 𐌳(𐌿) 𐌸𐌰𐌿𐍂𐍆𐍄𐌰𐌹 𐌽𐌹 𐍆𐌰𐌹𐍂𐍂𐌹𐌽𐌽𐌰𐌽𐌳, 𐌰𐌺 𐌼𐌰𐌹𐍃 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐌰.',
        5: '𐌸𐌰𐍄𐌰 𐌰𐌿𐌺 𐍅𐌹𐍄𐌴𐌹𐌸, 𐌺𐌿𐌽𐌽𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐍈𐌰𐌶𐌿 𐌷𐍉𐍂𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐌲𐌰𐌻𐌹𐌿𐌲𐌰𐌲(𐌿)𐌳𐌴 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐌰𐍃𐍃𐌰𐌿𐍃, 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐌸 𐌰(𐍂)𐌱𐌹 𐌹𐌽 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐌰𐌹 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌾𐌰𐌷 𐌲𐌿𐌳𐌹𐍃.',
        6: '𐌽𐌹 𐌼𐌰𐌽𐌽𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃𐌻𐌿[𐍃]𐍄𐍉 𐌻𐌰𐌿𐍃𐌰𐌹𐌼 𐍅𐌰𐌿𐍂𐌳𐌰𐌼, 𐌸𐌰𐌹𐍂𐌷 𐌸𐍉𐌴𐌹 (𐌵)𐌹𐌼𐌹𐌸 𐌷𐌰𐍄𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐌰 𐍃𐌿𐌽𐌿𐌼 𐌿𐌽(𐌲𐌰)𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃.',
        7: '𐌽𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌽𐌿 (𐌲𐌰𐌳)𐌰𐌹𐌻𐌰𐌽𐍃 𐌹𐌼.',
        8: '𐍅𐌴𐍃𐌿𐌸 𐌰𐌿𐌺 𐍃𐌿𐌼𐌰𐌽 (𐍂)𐌹(𐌵)𐌹𐌶, 𐌹𐌸 𐌽𐌿 𐌻𐌹𐌿𐌷𐌰𐌸 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽; 𐍃𐍅𐌴 𐌱𐌰𐍂𐌽𐌰 𐌻𐌹𐌿𐌷𐌰𐌳𐌹𐍃 𐌲𐌰𐌲𐌲𐌰𐌹𐌸. -',
        9: '𐌰𐌸𐌸𐌰𐌽 𐌰𐌺𐍂𐌰𐌽 𐌻𐌹𐌿𐌷𐌰𐌳𐌹𐍃 𐌹𐍃𐍄 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐍃𐌴𐌻𐌴𐌹𐌽 𐌾𐌰𐌷 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌾𐌰𐌷 𐍃𐌿𐌽𐌾𐌰𐌹. -',
        10: '𐌲𐌰𐌺𐌹𐌿𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐍃𐌹𐌾𐌰𐌹 𐍅𐌰𐌹𐌻𐌰 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌸 𐍆𐍂𐌰𐌿𐌾𐌹𐌽,',
        11: '𐌾𐌰𐌷 𐌽𐌹 𐌲𐌰𐌼𐌰𐌹𐌽𐌾𐌰𐌹𐌸 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐍂𐌹𐌵𐌹𐌶𐌹𐍃....',
        17: '𐌳𐌿𐌸𐌸𐌴 𐌽𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌿𐌽𐍆𐍂𐍉𐌳𐌰𐌹, 𐌰𐌺 𐍆𐍂𐌰𐌸𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍈𐌰 𐍃𐌹𐌾𐌰𐌹 𐍅𐌹𐌻𐌾𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃.',
        18: '𐌾𐌰𐌷 𐌽𐌹 𐌰𐌽𐌰𐌳𐍂𐌹𐌲𐌺𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍅𐌴𐌹𐌽𐌰, 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐌹𐍃𐍄 𐌿𐍃𐍃𐍄𐌹𐌿𐍂𐌴𐌹, 𐌰𐌺 𐍆𐌿𐌻𐌻𐌽𐌰𐌹𐌸 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽,',
        19: '𐍂𐍉𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐍀𐍃𐌰𐌻𐌼𐍉𐌼 𐌾𐌰𐌷 𐌷𐌰𐌶𐌴𐌹𐌽𐌹𐌼 𐌾𐌰𐌷 𐍃𐌰𐌲𐌲𐍅𐌹𐌼 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌹𐌼, 𐍃𐌹𐌲𐌲𐍅𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼 𐍆𐍂𐌰𐌿𐌾𐌹𐌽,',
        20: '𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌽𐌳𐌰𐌽𐍃 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐍆𐍂𐌰𐌼 𐌰𐌻𐌻𐌰𐌹𐌼 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌰𐍄𐍄𐌹𐌽 𐌾𐌰𐌷 𐌲𐌿𐌳𐌰,',
        21: '𐌿𐍆𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌹𐌽 𐌰𐌲𐌹𐍃𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.',
        22: '𐌵𐌴𐌽𐌴𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌼 𐌰𐌱𐌽𐌰𐌼 𐌿𐍆𐌷𐌰𐌿𐍃𐌾𐌰𐌹𐌽𐌰 𐍃𐍅𐌰𐍃𐍅𐌴 𐍆𐍂𐌰𐌿𐌾𐌹𐌽;',
        23: '𐌿𐌽𐍄𐌴 𐍅𐌰𐌹𐍂 𐌹𐍃𐍄 𐌷𐌰𐌿𐌱𐌹𐌸 𐌵𐌴𐌽𐌰𐌹𐍃 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌷𐌰𐌿𐌱𐌹𐌸 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽𐍃, 𐌾𐌰𐌷 𐌹𐍃 𐌹𐍃𐍄 𐌽𐌰𐍃𐌾𐌰𐌽𐌳𐍃 𐌻𐌴𐌹𐌺𐌹𐍃.',
        24: '𐌰𐌺𐌴𐌹 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉 𐌿𐍆𐌷𐌰𐌿𐍃𐌴𐌹𐌸 𐍇𐍂𐌹𐍃𐍄𐌿, 𐍃𐍅𐌰𐌷 𐌵𐌴𐌽𐌴𐍃 𐌰𐌱𐌽𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰.',
        25: '𐌾𐌿𐍃 𐍅𐌰𐌹𐍂𐍉𐍃 𐍆𐍂𐌹𐌾𐍉𐌸 𐌵𐌴𐌽𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐍉𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽 𐌾𐌰𐌷 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐌰𐍄𐌲𐌰𐍆 𐍆𐌰𐌿𐍂 𐌸𐍉,',
        26: '𐌴𐌹 𐌸𐍉 𐌲𐌰𐍅𐌴𐌹𐌷𐌰𐌹𐌳𐌴𐌳𐌹 𐌲𐌰𐌷𐍂𐌰𐌹𐌽𐌾𐌰𐌽𐌳𐍃 𐌸𐍅𐌰𐌷𐌻𐌰 𐍅𐌰𐍄𐌹𐌽𐍃 𐌹𐌽 𐍅𐌰𐌿𐍂𐌳𐌰,',
        27: '𐌴𐌹 𐌿𐍃𐍄𐌰𐌿𐌷𐌹 𐍃𐌹𐌻𐌱𐌰 𐍃𐌹𐍃 𐍅𐌿𐌻𐌸𐌰𐌲𐌰 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽, 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳𐌴𐌹𐌽 𐍅𐌰𐌼𐌼𐌴 𐌰𐌹𐌸𐌸𐌰𐌿 𐌼𐌰𐌹𐌻𐌴 𐌰𐌹𐌸𐌸𐌰𐌿 𐍈𐌰 𐍃𐍅𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌶𐌴, 𐌰𐌺 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹 𐍅𐌴𐌹𐌷𐌰 𐌾𐌰𐌷 𐌿𐌽𐍅𐌰𐌼𐌼𐌰.',
        28: '𐍃𐍅𐌰 𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐍉𐍃 𐍃𐌺𐌿𐌻𐌿𐌽 𐍆𐍂𐌹𐌾𐍉𐌽 𐍃𐌴𐌹𐌽𐍉𐍃 𐌵𐌴𐌽𐌹𐌽𐍃 𐍃𐍅𐌴 𐌻𐌴𐌹𐌺𐌰 𐍃𐌴𐌹𐌽𐌰. [𐍃𐌴𐌹𐌽 𐍃𐌹𐌻𐌱𐌹𐌽𐍃 𐌻𐌴𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌸,] 𐍃𐌰𐌴𐌹 𐍃𐌴𐌹𐌽𐌰 𐌵𐌴𐌽 𐍆𐍂𐌹𐌾𐍉𐌸, [𐌾𐌰𐌷] 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐍆𐍂𐌹𐌾𐍉𐌸.',
        29: '𐌽𐌹 𐌰𐌿𐌺 𐌼𐌰𐌽𐌽𐌰 𐍈𐌰𐌽𐌷𐌿𐌽 𐍃𐌴𐌹𐌽 𐌻𐌴𐌹𐌺 𐍆𐌹𐌾𐌰𐌹𐌳𐌰, 𐌰𐌺 𐍆𐍉𐌳𐌴𐌹𐌸 𐌹𐍄𐌰 𐌾𐌰𐌷 𐍅𐌰𐍂𐌼𐌴𐌹𐌸 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽....',
    },
    6: {
        8: '.... 𐍄𐌰𐌿𐌾𐌹𐌸 𐌸𐌹𐌿𐌸𐌹𐍃, 𐌸𐌰𐍄𐌰 𐌲𐌰𐌽𐌹𐌼𐌹𐌸 𐌰𐍄 𐍆𐍂𐌰𐌿𐌾𐌹𐌽, 𐌾𐌰𐌸𐌸𐌴 𐍃𐌺𐌰𐌻𐌺𐍃 𐌾𐌰𐌸𐌸𐌴 𐍆𐍂𐌴𐌹𐍃.',
        9: '.... 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌼 𐍈𐍉𐍄𐍉𐍃, 𐍅𐌹𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌼 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍃𐌰𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌰 𐌹𐍃𐍄 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼, 𐌾𐌰𐌷 𐍅𐌹𐌻𐌾𐌰𐌷𐌰𐌻𐌸𐌴𐌹 𐌽𐌹𐍃𐍄 𐌰𐍄 𐌹𐌼𐌼𐌰. 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽𐍃 [𐌾𐌰𐌷 𐌾𐌿𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽𐍃] 𐌸𐌰𐍄𐌰 𐍃𐌰𐌼𐍉 𐍄𐌰𐌿𐌾𐌰𐌹𐌸 𐍅𐌹𐌸𐍂𐌰 𐌹𐌽𐍃, 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌼 𐍈𐍉𐍄𐍉𐍃, 𐍅𐌹𐍄𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌼 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍃𐌰𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌰 𐌹𐍃𐍄 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼, 𐌾𐌰𐌷 𐍅𐌹𐌻𐌾𐌰𐌷𐌰𐌻𐌸𐌴𐌹 𐌽𐌹𐍃𐍄 𐌰𐍄 𐌹𐌼𐌼𐌰.',
        10: '𐌸𐌰𐍄𐌰 𐌽𐌿 𐌰𐌽𐌸𐌰𐍂, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃 𐌼𐌴𐌹𐌽𐌰𐌹, 𐌹𐌽𐍃𐍅𐌹𐌽𐌸𐌾𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽 𐌼𐌰𐌷𐍄𐌰𐌹 𐍃𐍅𐌹𐌽𐌸𐌴𐌹𐌽𐍃 𐌹𐍃. 𐌸𐌰𐍄𐌰 𐌽𐌿 𐌰𐌽𐌸𐌰𐍂, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃 𐌼𐌴𐌹𐌽𐌰𐌹, 𐌹𐌽𐍃𐍅𐌹𐌽(𐌸)𐌾𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽 𐌼𐌰𐌷𐍄𐌰𐌹 𐍃𐍅𐌹𐌽𐌸𐌴𐌹𐌽𐍃 𐌹𐍃.',
        11: '𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐍃𐌰𐍂𐍅𐌰𐌼 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐍃𐍄𐌰𐌽𐌳𐌰𐌽 𐍅𐌹𐌸𐍂𐌰 𐌻𐌹𐍃𐍄𐌹𐌽𐍃 𐌳𐌹𐌰𐌱𐌿𐌻𐌰𐌿𐍃; 𐌲𐌰𐌷𐌰𐌼𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐍃𐌰𐍂𐍅𐌰𐌼 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐍃𐍄𐌰𐌽𐌳𐌰𐌽 𐍅𐌹𐌸𐍂𐌰 𐌻𐌹𐍃𐍄𐌹𐌽𐍃 𐌳𐌹𐌰𐌱𐌿𐌻𐌰𐌿𐍃;',
        12: '𐌿𐌽𐍄𐌴 𐌽𐌹𐍃𐍄 𐌹𐌶𐍅𐌹𐍃 𐌱𐍂𐌰𐌺𐌾𐌰 𐍅𐌹𐌸𐍂𐌰 𐌻𐌴𐌹𐌺 𐌾𐌰𐌷 𐌱𐌻𐍉𐌸, 𐌰𐌺 𐍅𐌹𐌸𐍂𐌰 𐍂𐌴𐌹𐌺𐌾𐌰 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰, 𐍅𐌹𐌸𐍂𐌰 𐌸𐌰𐌽𐍃 𐍆𐌰𐌹𐍂𐍈𐌿 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐍂𐌹𐌵𐌹𐌶𐌹𐍃 𐌸𐌹𐍃, 𐍅𐌹𐌸𐍂𐌰 𐌸𐍉 𐌰𐌷𐌼𐌴𐌹𐌽𐍉𐌽𐌰 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽𐍃 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌼. 𐌿𐌽𐍄𐌴 𐌽𐌹𐍃𐍄 𐌹𐌶𐍅𐌹𐍃 𐌱𐍂𐌰𐌺𐌾𐌰 𐍅𐌹𐌸𐍂𐌰 𐌻𐌴𐌹𐌺 𐌾𐌰𐌷 𐌱𐌻𐍉𐌸, 𐌰𐌺 𐍅𐌹𐌸𐍂𐌰 𐍂𐌴𐌹𐌺𐌾𐌰 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌰, 𐍅𐌹𐌸𐍂𐌰 𐌸𐌰𐌽𐍃 𐍆𐌰𐌹𐍂𐍈𐌿 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽𐍃 𐍂𐌹𐌵𐌹𐌶𐌹𐍃 𐌸𐌹𐍃, 𐍅𐌹𐌸𐍂𐌰 𐌸𐍉 𐌰𐌷𐌼𐌴𐌹𐌽𐍉𐌽𐌰 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽𐍃 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌷𐌹𐌼𐌹𐌽𐌰𐌺𐌿𐌽𐌳𐌰𐌼.',
        13: '𐌳𐌿𐌸𐌸𐌴 𐌽𐌹𐌼𐌹𐌸 𐍃𐌰𐍂𐍅𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐌰𐌽𐌳𐍃𐍄𐌰𐌽𐌳𐌰𐌽 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌿𐌱𐌹𐌻𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐌿𐍃𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐍄𐌰𐌽𐌳𐌰𐌽. 𐌳𐌿𐌸𐌸𐌴 𐌽𐌹𐌼𐌹𐌸 𐍃𐌰𐍂𐍅𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌼𐌰𐌲𐌴𐌹𐌸 𐌰𐌽𐌳𐍃𐍄𐌰𐌽𐌳𐌰𐌽 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌿𐌱𐌹𐌻𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐌿𐍃𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐍄𐌰𐌽𐌳𐌰𐌽.',
        14: '𐍃𐍄𐌰𐌽𐌳𐌰𐌹𐌸 𐌽𐌿, 𐌿𐍆𐌲𐌰𐌿𐍂𐌳𐌰𐌽𐌰𐌹 𐌷𐌿𐍀𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐍃 𐍃𐌿𐌽𐌾𐌰𐌹 𐌾𐌰𐌲~𐌲𐌰𐍀𐌰𐌹𐌳𐍉𐌳𐌰𐌹 𐌱𐍂𐌿𐌽𐌾𐍉𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽𐍃, 𐍃𐍄𐌰𐌽𐌳𐌰𐌹𐌸 𐌽𐌿, 𐌿𐍆𐌲𐌰𐌿𐍂𐌳𐌰𐌽𐌰𐌹 𐌷𐌿𐍀𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐍃 𐍃𐌿𐌽𐌾𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐍀𐌰𐌹𐌳𐍉𐌳𐌰𐌹 𐌱𐍂𐌿𐌽𐌾𐍉𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽𐍃,',
        15: '𐌾𐌰𐌲~𐌲𐌰𐍃𐌺𐍉𐌷𐌰𐌹 𐍆𐍉𐍄𐌿𐌼 𐌹𐌽 𐌼𐌰𐌽𐍅𐌹𐌸𐌰𐌹 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽𐍃 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌾𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍃𐌺𐍉𐌷𐌰𐌹 𐍆𐍉𐍄𐌿𐌼 𐌹𐌽 𐌼𐌰𐌽𐍅𐌹𐌸𐌰𐌹 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽𐍃 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌾𐌹𐍃',
        16: '𐌿𐍆𐌰𐍂 𐌰𐌻𐌻 𐌰𐌽𐌳𐌽𐌹𐌼𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌺𐌹𐌻𐌳𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌸𐌰𐌼𐌼𐌴𐌹 𐌼𐌰𐌲𐌿𐌸 𐌰𐌻𐌻𐍉𐍃 𐌰𐍂𐍈𐌰𐌶𐌽𐍉𐍃 𐌸𐌹𐍃 𐌿𐌽𐍃𐌴𐌻𐌾𐌹𐌽𐍃 𐍆𐌿𐌽𐌹𐍃𐌺𐍉𐍃 𐌰𐍆𐍈𐌰𐍀𐌾𐌰𐌽; 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻 𐌰𐌽𐌳𐌽𐌹𐌼𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌺𐌹𐌻𐌳𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃, 𐌸𐌰𐌼𐌼𐌴𐌹 𐌼𐌰𐌲𐌿𐌸 𐌰𐌻𐌻𐍉𐍃 𐌰𐍂𐍈𐌰𐌶𐌽𐍉𐍃 𐌸𐌹𐍃 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽𐍃 𐍆𐌿𐌽𐌹𐍃𐌺𐍉𐍃 𐌰𐍆𐍈𐌰𐍀𐌾𐌰𐌽;',
        17: '𐌾𐌰𐌷 𐌷𐌹𐌻𐌼 𐌽𐌰𐍃𐌴𐌹𐌽𐌰𐌹𐍃 𐌽𐌹𐌼𐌰𐌹𐌸 𐌾𐌰𐌷 𐌼𐌴𐌺𐌹 𐌰𐌷𐌼𐌹𐌽𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃; 𐌾𐌰𐌷 𐌷𐌹𐌻𐌼 𐌽𐌰𐍃𐌴𐌹𐌽𐌰𐌹𐍃 𐌽𐌹𐌼𐌰𐌹𐌸 𐌾𐌰𐌷 𐌼𐌴𐌺𐌹 𐌰𐌷𐌼𐌹𐌽𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃𐍄 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃;',
        18: '𐌸𐌰𐌹𐍂𐌷 𐌰𐌻𐌻𐍉𐍃 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌹𐌽𐍃 𐌾𐌰𐌷 𐌱𐌹𐌳𐍉𐍃 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰 𐌼𐌴𐌻𐌰 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽 𐌾𐌰𐌷 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 [𐌳𐌿]𐍅𐌰𐌺𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌿𐍃𐌳𐌰𐌿𐌳𐌴𐌹𐌽 𐌾𐌰𐌷 𐌱𐌹𐌳𐍉𐌼 𐍆𐍂𐌰𐌼 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼, 𐌸𐌰𐌹𐍂𐌷 𐌰𐌻𐌻𐍉𐍃 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌹𐌽𐍃 𐌾𐌰𐌷 𐌱𐌹𐌳𐍉𐍃 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰 𐌼𐌴𐌻𐌰 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽 𐌾𐌰𐌷 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐍅𐌰𐌺𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃𐌳𐌰𐌿𐌳𐌴𐌹𐌽 𐌾𐌰𐌷 𐌱𐌹𐌳𐍉𐌼 𐍆𐍂𐌰𐌼 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼,',
        19: '𐌾𐌰𐌷 𐍆𐍂𐌰𐌼 𐌼𐌹𐍃, 𐌴𐌹 𐌼𐌹𐍃 𐌲𐌹𐌱𐌰𐌹𐌳𐌰𐌿.... 𐌾𐌰𐌷 𐍆𐍂𐌰𐌼 𐌼𐌹𐍃, 𐌴𐌹 𐌼𐌹𐍃 𐌲𐌹𐌱𐌰𐌹𐌳𐌰𐌿 𐍅𐌰𐌿𐍂𐌳 𐌹𐌽 𐌿𐍃𐌻𐌿𐌺𐌰 𐌼𐌿𐌽𐌸𐌹𐍃 𐌼𐌴𐌹𐌽[𐌰]𐌹𐍃 𐌹𐌽 𐌱𐌰𐌻𐌸𐌴𐌹𐌽 𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐍂𐌿𐌽𐌰 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽𐍃,',
        20: '𐍆𐌰𐌿𐍂 𐌸𐍉𐌴𐌹 𐌰𐌹𐍂𐌹𐌽𐍉 𐌹𐌽 𐌺𐌿𐌽𐌰𐍅𐌹𐌳𐍉𐌼, 𐌴𐌹 𐌹𐌽 𐌹𐌶𐌰𐌹 𐌲𐌰𐌳𐌰𐌿𐍂𐍃𐌾𐌰𐌿, 𐍃𐍅𐌴 𐍃𐌺𐌿𐌻𐌾𐌰𐌿 𐍂𐍉𐌳𐌾𐌰𐌽.',
        21: '(𐌰𐌸𐌸𐌰)𐌽 𐌴𐌹 𐌾𐌿𐍃 𐍅𐌹𐍄𐌴𐌹𐌸 𐍈𐌰 𐌱𐌹 𐌼𐌹𐌺 𐌹𐍃𐍄, 𐍈𐌰 𐌹𐌺 𐍄𐌰𐌿𐌾𐌰, 𐌺𐌰𐌽𐌽𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐌻𐌻𐌰𐍄𐌰 𐍄𐍅𐌺𐌴𐌹𐌺𐌿𐍃 𐍃𐌰 𐌻𐌹𐌿𐌱𐌰 𐌱𐍂𐍉𐌸𐌰𐍂 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐌰 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽,',
        22: '𐌸𐌰𐌽𐌴𐌹 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃, 𐌳𐌿𐌸𐌸𐌴 𐌴𐌹 𐌺𐌿𐌽𐌽𐌴𐌹𐌸 (𐍈𐌰) 𐌱(𐌹) 𐌼𐌹𐌺 𐌹𐍃𐍄, 𐌾𐌰𐌷 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌾𐌰𐌹 𐌷𐌰𐌹𐍂𐍄𐍉𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰.',
        23: '𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌱𐍂𐍉𐌸𐍂𐌿𐌼 𐌾𐌰𐌷 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌼𐌹𐌸 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌰𐍄𐍄𐌹𐌽 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿.',
        24: '𐌰𐌽𐍃𐍄𐍃 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌽𐌳 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌽𐌰 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿 𐌹𐌽 𐌿𐌽𐍂𐌹𐌿𐍂𐌴𐌹𐌽. 𐌰𐌼𐌴𐌽. [(Ephesians 6:25) 𐌳𐌿 𐌰𐌹𐍆𐌰𐌹𐍃𐌹𐌿𐌼 𐌿𐍃𐍄𐌰𐌿𐌷.]',
    },
}
